// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":101,"question":"أثناء إجراء بعض العمليات تبتل الملابس -حتى الداخلية- والجلد بالدم والبول، وقد يتكرر الأمر خلال اليوم، فهل على الطبيب الغُسل عند ذلك أم يُجزئ الوضوء؟","title":"حكم ما يصيب ثياب الطبيب أثناء الجراحة","answer":"الجواب: عليه أن يغسل ما أصابه، أو يبدل الثياب بثياب سليمة، وما أصاب البدن: الرِّجْل، أو اليد، أو نحوه، يغسله، وما عليه غُسل. عليه أن يَغْسِلَ ما أصابه فقط: ما أصاب البدن، أو ما أصاب الثوب إذا كان يُصلي فيه، أو يبدله بغيره ويُصلي بثوبٍ سليم، وما أصاب الرِّجْل أو الرأس أو الوجه يُغسل.","link":"https://binbaz.org.sa/fatwas/3195/حكم-ما-يصيب-ثياب-الطبيب-اثناء-الجراحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0081.mp3","categories":["النجاسات وإزالتها"]},{"id":227,"question":"ما حكم المَنِيّ على اللباس؟ طاهر أم نجس؟","title":"ما حكم ما يصيب الثياب من المَنِيّ؟","answer":"الجواب: المني طاهر في أصح قولي العلماء، فإذا كان في ثوبك وصليت فيه فالصلاة صحيحة، لكن الأفضل حَكُّه إن كان يابسًا، وغسله إن كان رطبًا، هذا هو الأفضل، فقد كان يُغسل من ثوب النبي عليه الصلاة والسلام، وكانت عائشةُ تحكُّه من ثوبه إذا كان يابسًا.","link":"https://binbaz.org.sa/fatwas/4074/ما-حكم-ما-يصيب-الثياب-من-المني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0234.mp3","categories":["النجاسات وإزالتها"]},{"id":293,"question":"هل إفرازات المرأة -سواء كانت متزوجةً أم لا- طاهرةٌ أم لا، على اللباس؟","title":"حكم الإفرازات التي تخرج من المرأة","answer":"الجواب: هذا محل نظرٍ، ما يخرج منها من السَّائلات فالأصل فيه أنه كالبول، هذا هو الأصل، أما الرطوبة العادية التي تكون رطوبةً بدون سائلٍ فهذه أمرها سهل، لكن الشيء الذي يخرج ويسيل من الفرج فهذا حكمه حكم البول، الذي يظهر لنا أنه نجسٌ يتحرز منه، كالقطرة ونحوها.\nوهذا إذا كان مستمرًّا معها، تتحرز منه، أما إذا كان يعرض ويزول فهذا يكفي فيه الاستنجاء، والحمد لله.","link":"https://binbaz.org.sa/fatwas/4295/حكم-الافرازات-التي-تخرج-من-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0342.mp3","categories":["قضايا المرأة","النجاسات وإزالتها","التيمم"]},{"id":759,"question":"كثير من الطلبة يلبسون أحذيةً محفورة الأرضية، وهذه الأحذية مُحاطة برباطٍ من قماشٍ، فإذا دخلوا دورة المياه علق ما فيها من مياه وغيرها من أسفل الحذاء، وفي الرباط المحيط بالحذاء، وعند دعكه بالأرض يبقى ما علق بالرباط وما علق بأسفل الحذاء، ثم لا تُخلع هذه الأحذية عند الدخول إلى المسجد؛ لما يتصاعد من روائح من الجوارب، فما حكم صلاة الطلبة في هذه الحال؟ وما حكم الصلاة على هذا الفرش؟ جزاكم الله خيرًا والسلام.","title":"حكم الصلاة بالأحذية التي بها نجاسة","answer":"الجواب: هذه الأحذية طهورها التراب، فبعد الخروج من الحمام إذا مرَّ على الأرض صارت لها طهورًا، يقول النبيُّ ﷺ لما أخبره جبرائيل أنَّ في نعليه أذى، وكان يُصلي فيهما، فخلعهما، فلما رآه الصحابةُ خلع خلعوا نعالهم، فلما سلَّم عليه الصلاة والسلام قال: لماذا خلعتُم نعالكم؟ قالوا: لأنك خلعتَ نعليك، قال: لأن جبرائيل أتاني فأخبرني أنَّ بهما خبثًا فخلعتُهما، فإذا أتى أحدُكم المسجدَ فلينظر، فإن رأى في نعليه قذرًا أو أذًى فليمسحه بالتراب، ثم يُصلي فيهما.\nفإذا كان عليه حذاء يدخل فيه الحمام ويتوضأ فيه فإنه يمسحه بالتراب إذا بقي فيه أذى من رطوبةٍ، فإن لم يتيسر ذلك يخلعه عند الباب، أو في موضعٍ آخر، ويُصلي بدونه؛ حتى لا يُؤذي إخوانه، ولا يؤذي الفرش، ولا يُكدِّر على المصلين صلاتهم، يخلعه لأنه قد غسل رجليه، فيخلعه في أي مكانٍ ويُصلي حافيًا، فقد ثبت عنه عليه الصلاة والسلام أنه كان ربما يصلي حافيًا ومُنْتَعِلًا عليه الصلاة والسلام.\nوالمساجد اليوم فُرشت، وكان فيما مضى رمل أو حصباء، أما اليوم فقد فُرشت، فتتأثر بالتراب، وتتأثر بالغبار، وتتأثر بالرطوبة، فالأوْلى في مثل هذه الحال مراعاة شعور المصلين، ومراعاة نظافة الفرش بخلع هذه الأحذية في مكانٍ في مقدم المسجد عند الباب؛ حرصًا على طهارة الفُرُش ونظافتها وعدم تنفير المصلين منها، والرسول ﷺ عظَّم المساجد، وأمر بتنظيفها وتطهيرها وإخراج القَذَى منها، فهذا من ذلك، هذا الأمر من ذلك، داخلٌ في العموم؛ لأنها الأحوال تغيرت، وصارت المساجد بعد التراب والرمال والحصاء صارت إلى فُرُشٍ تُجهز بأموالٍ جزيلةٍ، والناس يتأثرون بما قد يقع فيها من أوساخٍ وأتربةٍ، وربما نفَّرتهم عن الصلاة في المساجد، أو أداء الصلاة على تقزُّزٍ، وعلى تكلُّفٍ -نسأل الله للجميع التَّوفيق. \nس: هناك روائح تتصاعد من الأرجل؛ لمكث الرِّجْل في الحذاء مدةً طويلةً، وخاصة الطلبة العسكريين، فهل الأولى أن تتصاعد الروائح وتُؤذي المصلين أم يلبس الحذاء ولا تكون هناك روائح، وقد يتسخ الفراش من الغبار؟ أيُّهما أولى: أن يُصلي وهو مرتاح، أو يُصلي والروائح تُضايقه؟\nالشيخ: يُراعي الأصلح، إذا كان الحذاء نظيفًا ولا يُؤذي أحدًا صلَّى فيه، لا فراشًا ولا أذى، صلى فيه، فأما إذا كان يُؤذي أو يُسبب تقذُّرًا للفرش وتنفيرًا للمُصلين تركه وصلَّى، والروائح التي في رجله يسيرة، أمرها يسير، ولو وجد فيها شيء فأمرها يسير؛ لأنها من جنس زملائه، كلهم في أرجلهم ما في الرِّجْل الأخرى، وكل هذا لا يضرُّهم، فهو شيء يسير مُغتفر بالنسبة لما قد يترتب على الأحذية من أوساخٍ وقذارات للفرش عند عدم المبالاة؛ لأنَّ بعض الناس لا يُبالي ولا يهتم بالحذاء، ولا يحرص على نظافته.","link":"https://binbaz.org.sa/fatwas/20662/حكم-الصلاة-بالاحذية-التي-بها-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0578ما حكم الصلاة بالأحذية التي بها نجاسة؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":934,"question":"هل الخمر نجسة نجاسة عينية؟ وما حكم استعمال الكولونيا؟","title":"هل نجاسة الخمر عينية؟ وما حكم الكولونيا؟","answer":"الجواب: الخمر عند جمهور أهل العلم نجسة، والله حرَّمها، والرسول لما حرَّمها الربُّ  أمر بإراقتها، وذهب جمهورُ أهل العلم إلى أنها نجسة؛ لأنها خبيثة، وهي أم الخبائث.\nفالذي عليه جمهورُ أهل العلم أنها نجسة، ينبغي غسل ما أصاب الثوبَ منها، وغسل الأواني بعدها.\nوقال قومٌ: إنها طاهرة؛ لأنها من العنب، أو التمر، أو العسل، أو نحو ذلك، لكن تجب إراقتها في الحال، متى تخمَّرت وجب إتلافها.\nولكن قول الجمهور بنجاستها قولٌ قوي؛ لأنها خبيثة، والخبث هو النّجس الذي أصاب البول والغائط، البول والغائط أصله ماء، أصل البول ماء، وأصل الغائط طعام: تمر ولحم وخبز، فلما تغيّرت حاله وخبث صار نجسًا، هكذا أصل الخمر من العنب، ومن التمر، ومن العسل، ومن البُرِّ، ومن الشعير، ومن غير ذلك، وبتخمّره وشدَّته وإسكاره صار خبيثًا.\nوالقول بنجاسته قولٌ قوي، كما هو قول الأكثرين، وهو من وسائل الحذر منه، وعدم بقائه، وإراقته وإتلافه.\nوالكولونيا كذلك خبيثة؛ لأنَّ فيها إسبرت، وهي مسكرة، فالواجب ترك استعمالها، وقد علم الناسُ سُكرها، وقد يتعاطاها بعضُ السُّفهاء فيسكرون.\nوقد سألنا جماعةً من الأطباء عنها، فذكروا عنها أنها تُسْكِر لما فيها من الإسبرت، فالواجب عدم استعمالها، لا في الفرش، ولا في الأيدي، كثيرٌ من الناس يتساهلون فيها، ولا ينبغي التَّساهل فيها.","link":"https://binbaz.org.sa/fatwas/20979/هل-نجاسة-الخمر-عينية-وما-حكم-الكولونيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0775هل الخمر نجسة نجاسة عينية وما حكم استعمال الكلونيا؟ ابن باز فتاوى المحاضرات.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":1280,"question":"يوجد لدينا بالمُستشفى مياه مجاري مُكررة، ونتعرض لتلك المياه في كثيرٍ من الأماكن من جرَّاء ري الحدائق، وقد نتعرض ولو لرذاذٍ منها، فهل تلك المياه نجسة تُبطل الوضوء؟ وهل الأشجار التي تُروى منها يجوز أكل ثمارها أم لا؟","title":"ما حكم سقي الزرع بمياه المجاري المكررة؟","answer":"الجواب:\nإذا كانت هذه المياه قد كُرِّرت حتى ذهبت منها رائحةُ النَّجاسة وطعمُ النَّجاسة ولونها، وصارت مياهًا عذبةً طيبةً سليمةً؛ فلا حرج في ذلك، يكون لها حكمُ الطَّهارة، وما يُصيب الناسَ منها لا يضرّ، والشجر الذي يُسقى بها لا يضرّ، وثمره لا بأس به.\nأما إذا كان لا، بقي فيها أثرُ النَّجاسة، فلا، لا تُستعمل: لا في الأشجار، ولا في غيرها، بل تُزال إلى جهةٍ أخرى، لا تُؤذي المسلمين.\nأما إن كانت قد كُررت تكريرًا كاملًا وزالت منها آثارُ النَّجاسة: لا لونًا، ولا طعمًا، ولا ريحًا؛ فالحمد لله.","link":"https://binbaz.org.sa/fatwas/21325/ما-حكم-سقي-الزرع-بمياه-المجاري-المكررة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1068ما حكم المياه المجاري المكررة فيي سقيا الزرع؟ ابن باز.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":1595,"question":"أبوال البهائم والدم هل هو نجس؟","title":"حكم دماء وأبوال البهائم","answer":"الجواب:\nالمأكولة بولها وروثها طاهر، أما الدم فلا، الدم المسفوح نجس، لكن بولها وروثها -إبل أو بقر أو غنم- مما يُؤكَل طاهر.\nس: والحصان؟\nج: والحصان، الخيل بولها طاهر؛ لأنها مأكولة.","link":"https://binbaz.org.sa/fatwas/21699/حكم-دماء-وابوال-البهاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم دم وأبوال الحيوانات.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":1732,"question":"بالنسبة للنساء في الحج: إذا تعذَّر وجود الماء، هل يكفيهم مسح الإفرازات والتيمم للصلاة؟","title":"حكم الإفرازات التي تأتي النساء في الحج","answer":"الجواب:\nأي إفرازات؟\nس: الإفرازات التي تأتي من الرحم؟\nج: تستنجي ثم تتوضأ، إلا إذا كانوا في برٍّ ما عندهم ماء، فإنها تستجمر وتتيمم، أما التي في مكة فالحمد لله الماء موجود، فتستنجي.\nس: إذا كان في الثوب شيءٌ من هذه الإفرازات؟\nج: يُغْسَل ما أصابه.\nس: ما يُفْرَك؟\nج: يُغْسَل ما أصابه.\nس: يُعتبر نجسًا؟\nج: نعم.\nس: عادة النساء في منى ومُزدلفة أنه يتعذَّر وجود المكان الذي يستترن فيه فيضطررن للتيمم، بعذر أن ما في مكان يستترن فيه؟\nج: يلتمسن طرف الخيمة: تبول فيه وتستجمر، وتأخذ التراب وتمسح ثلاث مراتٍ أو أربع مراتٍ حتى يزول الأذى.","link":"https://binbaz.org.sa/fatwas/21839/حكم-الافرازات-التي-تاتي-النساء-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإفرازات التي تأتي النساء في الحج.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":1869,"question":"أشخاص يعملون سائسين للكلاب التي تكشف المخدرات، ويلبسون لباسًا خاصًّا للتدريب، يقولون: كيف نُصلي إذا جاء وقتُ الصلاة؟","title":"ما حكم مَن يعمل سائسًا للكلاب البوليسية؟","answer":"الجواب:\nالكلاب البوليسية يعني؟\nس: نعم الكلاب البوليسية، يقولون: كيف نصلي إذا جاء وقت الصلاة؟ يخافون أن يكون الكلبُ قد ولغ على اللباس وكذا؟\nج: نصيحتنا لهم أن يلتمسوا خدمةً غير هذه الخدمة، وإلا فالواجب عليهم إذا رأوا شيئًا أن يغسلوه، وإن لم يروا شيئًا فالأصل الطهارة، فإن جاء لعابُ الكلب على ثوب أحدهم فعليه أن يغسله سبع مرات، هذا هو الأحوط، وإن ما رأى شيئًا فالأصل السلامة، لكن إذا تيسَّرت لهم خدمة غير هذه؛ كان ذلك أحسن لهم.\nس: مع أنها تكشف وتفيد؟\nج: البعد عنها أسلم -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21978/ما-حكم-من-يعمل-ساىسا-للكلاب-البوليسية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استخدام الكلاب البوليسية.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":2087,"question":"أثر الخمر في الثياب؟","title":"ما حكم الثياب يصيبها شيء من الخمر؟","answer":"الجواب:\nينبغي غسله احتياطًا؛ لأنَّ الجمهور يرون أنَّه نجس، فيُغْسَل من باب الاحتياط.","link":"https://binbaz.org.sa/fatwas/22205/ما-حكم-الثياب-يصيبها-شيء-من-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أثر الخمر في الثياب.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":2245,"question":"يُؤخذ من هذا الحديث (في الأعرابي الذي بال في المسجد) أن البول إذا وقع في المسجد أو في أي مكانٍ أنه يكفي أن يصبّ عليه الماء؟","title":"هل يكفي صبُّ الماء على ما أصابه البول؟","answer":"الجواب:\nنعم، يُكاثر بالماء ويكفي، في المسجد، أو على البساط، أو في المجلس، أو ما أشبه ذلك.\nس: ما يحتاج إلى فَرْكٍ؟\nج: نعم لا يحتاج إلى شيءٍ.\nس: إذا وضع سجادةً أو شيئًا وسجد، ألا يكفي؟\nج: المقصود: الشيء الذي من جنس البساط، والسجادة، والأرض، كلها يكفيها المكاثرة بالماء.","link":"https://binbaz.org.sa/fatwas/22368/هل-يكفي-صب-الماء-على-ما-اصابه-البول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث بَال أَعْرَابيٌّ في المسجِد... هل يكفي أن يصبّ عليه الماء.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":2326,"question":"رجلٌ يسأل فيقول: إنَّه بعدما يخرج منه بولٌ أو مَذْيٌ أو وَدْيٌ ويستنجي بالماء، يقول: ثم أمشي أو أقوم أو أقعد فيخرج بولٌ يسيرٌ أو مَذْيٌ يسيرٌ أو وَدْيٌ يسيرٌ على حسب الذي استنجيتُ منه، فإذا حدث هذا هل أمسح بمنديلٍ أو نحوه؟","title":"حكم من به سلس أو يخرج منه مَذْيٌ أو وَدْيٌ","answer":"الجواب: لا، يُعيد الاستنجاء، إلا أن يكون مستمرًّا، يعني: غالبًا عليه؛ فيكون من باب السَّلس.\nس: يقول: لي سنة ونصف؟\nج: إذا كان غالبًا عليه، أمَّا إن كان في الوقت الحاضر فيُعيد الاستنجاء.\nس: أفتاه الأطباء وقالوا: توضأ ثم صلِّ ولا عليك؟\nج: الأطباء ما هم علماء، عليه أن يُعيد الاستنجاء، إلا إذا غلب عليه وصار من أصحاب السَّلس؛ فيتوضأ إذا دخل الوقتُ، ويستنجي إذا دخل الوقتُ ويكفي، وإذا خرج الوقتُ أعاد الاستنجاء.","link":"https://binbaz.org.sa/fatwas/22450/حكم-من-به-سلس-او-يخرج-منه-مذي-او-ودي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طهارة من به سلس أو يخرج منه مَذْيٌ أو وَدْيٌ.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":2418,"question":"الدم ما هو الدليل على نجاسته؟","title":"ما دليل نجاسة الدم وحكم صلاة المجروح؟","answer":"الجواب:\nأمر النبي ﷺ بغسله -غسل الدماء-، وحكى بعضهم إجماع أهل العلم على أنه نجس، إلا الشيء القليل يُعْفَى عنه، الدم القليل الذي من غير الدُّبُر ولا مِن غير الذَّكَر مثل ما يقع في الأسنان أو في العين أو الرعاف القليل؛ يُعْفَى عنه.\nس: وصلاة عمر  بالدم؟\nالشيخ: المجروح والمستحاضة يُعْفَى عنه، يصلي على حسب حاله، الذي جرحه يمشي يصلي على حسب حاله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ  [التغابن:16].","link":"https://binbaz.org.sa/fatwas/22546/ما-دليل-نجاسة-الدم-وحكم-صلاة-المجروح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدليل على نجاسة الدم.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":2755,"question":"النَّضْح الذي ورد في أحاديث غَسْل الثوب الذي أصابه دم الحيض هل يراد به الغَسْل؟","title":"هل المقصود بالنَّضْح على الثوب الغَسْل؟","answer":"الجواب: الغَسْل الغَسْل، تَنْضَحُه: تغسله، يعني كما في الرواية الأخرى: تغسل الدم حتى يزول.","link":"https://binbaz.org.sa/fatwas/22903/هل-المقصود-بالنضح-على-الثوب-الغسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المقصود بالنضح الغسل.mp3","categories":["شروح الحديث","النجاسات وإزالتها"]},{"id":2758,"question":"بول ما لا يُؤكل لحمُه، هل هو طاهر مثل الحُمُر؟","title":"حكم بول ما لا يُؤكل لحمُه","answer":"الجواب: نجس، ما في خلاف، مثل الحُمُر والهِرّ والكلب والبغال، كلها نجس.","link":"https://binbaz.org.sa/fatwas/22906/حكم-بول-ما-لا-يوكل-لحمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بول ما لا يؤكل لحمه.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":3772,"question":"غسل الفَرْج بعد الجماع للنزاهة أو للنجاسة؟","title":"هل يجب غسل الفَرْج بعد الجماع؟","answer":"الجواب: للاستنجاء لأجل الخارج، خروج المني بعد الجماع.\nس: ما أنزل؟\nالشيخ: ولو ما أنزل؛ لأن إدخال الفرج في الفرج لا بدّ أن يناله شيء من رطوبة البول، وغيره.","link":"https://binbaz.org.sa/fatwas/23968/هل-يجب-غسل-الفرج-بعد-الجماع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث إذا أراد أن ينام وهو جنب غسل فرجه، غسل الفرج للنزاهة أو للنجاسة.mp3","categories":["شروح الحديث","النجاسات وإزالتها"]},{"id":3899,"question":"هل ثمن الدم يدخل فيه ما يحتاجونه في المُستشفى؟","title":"هل يجوز أخذ مقابل على بذل الدم للمستشفى؟","answer":"الجواب: يدخل فيه، لا يُباع، ينبغي أنه يبذل من دون بيعٍ، من باب المساعدة، لكن لو اضطرَّ إليه جاز له أن يشتريه، وحرم على البائع.","link":"https://binbaz.org.sa/fatwas/24115/هل-يجوز-اخذ-مقابل-على-بذل-الدم-للمستشفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث نهى النبي عن ثمن الدّم، فما حكم ما يحتاجونه في المُستشفى.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4406,"question":"إذا كان أقلّ من قُلَّتين تقع فيه النَّجاسة؟","title":"حكم نجاسة الماء إذا كان أقلّ من قُلَّتين","answer":"الجواب: فيه الخلاف المذكور: من أهل العلم مَن يقول: إنه ينجس وإن لم يتغير.  وقول ثانٍ: لا ينجس إلا إذا تغير لونه أو ريحه أو طعمه.  إلا إذا كان قليلًا كمياه الأواني، فإن هذا يُراق، مثل: أمر النبي ﷺ بإراقة الإناء الذي ولغ فيه الكلب، الذي في الأواني يُراق؛ لأنَّ الغالب أنه تُؤثر فيه النَّجاسة؛ لأنه قليل.","link":"https://binbaz.org.sa/fatwas/24683/حكم-نجاسة-الماء-اذا-كان-اقل-من-قلتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نجاسة الماء إذا كان أقلّ من قُلَّتين.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":4407,"question":"الماء المغصوب؟","title":"هل تصح الطهارة بالماء المغصوب؟","answer":"الجواب: يحرم استعماله، الماء المغصوب مُحرَّم، لا لأجل أنه ما هو بطاهرٍ، هو طاهر، لكن ما يجوز؛ لأنك أخذتَه من صاحبه بغير حقٍّ.\nس: صحَّة الطَّهارة به؟\nج: الصحيح صحّة الطهارة؛ لأنَّ التحريم ما هو لأجل الطهارة، وإنما من أجل الظلم، مثلما تصحّ الصلاة على الأرض المغصوبة على الصحيح، لا لأنها جائزة، بل لأنَّ الطهارة تمت شروطها، لكن هو ظالم بغصبه إياها، واستيلائه عليها، وأخذه المال بغير حقٍّ، مطالب بهذا.\nس: استدلَّ المانعُ بحديث: إنَّ دماءكم وأموالكم وأعراضَكم عليكم حرام، فإن الطهارة لا تُجزئ؟\nج: حرام عليكم، لكن الطهارة صحيحة؛ لأنه ماء طهور توضأ به فأجزأه، لكنه ظالم بهذا، ولا تبطل الطهارة، كمَن صلَّى في الأرض المغصوبة؛ صحَّت صلاته وهو آثمٌ، المسألة خلافية، لكن هذا هو الأرجح.\nس: هو استدلَّ بهذا الحديث على عدم صحّة الطّهارة؟\nج: هذا يدل على التَّحريم فقط.","link":"https://binbaz.org.sa/fatwas/24684/هل-تصح-الطهارة-بالماء-المغصوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استعمال الماء المغصوب والطهارة به.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":4408,"question":"الترجمة الثانية: \"بَابُ الرَّدِّ عَلَى مَنْ جَعَلَ مَا يَغْتَرِفُ مِنْهُ الْمُتَوَضِّئُ بَعْدَ غَسْلِ وَجْهِهِ مُسْتَعْمَلًا\"؟","title":"حكم الماء الذي يغترف منه المتوضئ","answer":"الجواب: هذا حُجَّة على المؤلف.\nس: هذا ينافي ما قاله أولًا؟\nج: وهذا حُجَّة عليه؛ لأن إدخال يده في الإناء لا يجعله مستعملا، والنبي كان يدخل يديه أولا أدخلها في المضمضة والاستنشاق، ثم أدخلها لغسل وجهه، ثم أدخلها لغسل اليدين، إلى آخره.\nس: كيف الجمع بين هذا وهذا؟\nج: الجمع بأنَّ الماء ما زال في أعضاء الوضوء، فهو بحكم الطّهورية.\nس: فإذا انفصل؟\nج: فإذا انفصل صار إلى أنه طاهر دون طهور، وهذا دليلٌ على القول المشهور عند الحنابلة .. طاهر وطهور ونجس، وهو قول الشافعية وجماعة، والصواب أنه نوعان: طهور ونجس، والذي يُسمَّى: طاهرًا هو طهور، وإنما الطاهر فقط هي الجهة المضادة: كماء الورد، ماء الرمان، ماء العنب، هذه يُقال لها: ماء طاهرة فقط؛ لأنها مياه مُضاعفة مقيدة، ليست فيها مطلقة، أما الماء المطلق الذي قال الله فيه: فَلَمْ تَجِدُوا مَاءً [النساء:43]، فهذا حكمه الطّهارة، هذا الأصل، إلا إذا تغير بالنجاسة؛ صار نجسًا بالإجماع.\nس: ما يغترف منه المُتوضئ هذا طهور؟\nج: طاهر نعم، الطهورية باقية فيه ما دام تردد على الأعضاء، ولهذا يُزيل الأذى، الغسلة الأولى قد يكون هناك فيها شيء من أذى، ثم تأتي الثانية فتُزيل بقية الأذى، ثم تأتي الثالثة فتكمل، وكذلك ما قد يكون من نجاسةٍ في العضو، تُزيله الغسلة الأولى فتُخففه، ثم تأتي الثانية فتُخفف أو تُزيل، ثم تأتي الثالثة إلى أن تزول النّجاسة.","link":"https://binbaz.org.sa/fatwas/24685/حكم-الماء-الذي-يغترف-منه-المتوضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في حكم ما يغترف منه المتوضئ بعد غسل وجهه مستعملا.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":4411,"question":"مياه المجاري المُنقاة ..... التجارب؟","title":"ما الحكم في طهارة مياه المجاري المُنقاة؟","answer":"الجواب: إذا زال عنها الريحُ والطعمُ واللونُ لها حكم الطَّهارة.","link":"https://binbaz.org.sa/fatwas/24688/ما-الحكم-في-طهارة-مياه-المجاري-المنقاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طهارة مياه المجاري المُنقاة.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":4412,"question":"استنباط المؤلف في طهارة السّترة في الصلاة؟","title":"هل طهارة السُّترة شرط لصحة لصلاة؟","answer":"الجواب: من حديث أسماء، قال لها: ثم صَلِّي فيه، تغسله ثم تُصلي فيه، فدلَّ على ألا تُصلي فيه ما دام فيه النَّجاسة، لا بد من طهارة السّترة أيضًا والبدن، كلها، لا بد من طهارة الثلاثة: البدن، والبقعة، والملابس التي يُصلّى فيها، لا بد من طهارة الجميع، قوله جلَّ وعلا: وَثِيَابَكَ فَطَهِّرْ [المدثر:4] يعمّ ذلك.\nس: السترة ليست بقعةً ولا ثوبًا؟\nج: السترة التي تلبسها، ما هي السترة التي بالأمام، مقصوده اللباس، يعني هذا مقصوده، السترة التي تستتر بها المرأة.  أما السترة التي أمامه ما هو شرط أن تكون طاهرةً، المهم ما تستر به عورتها، لا بد أن تكون الملابس التي عليها طاهرةً كالرجل، سواء بسواء.","link":"https://binbaz.org.sa/fatwas/24689/هل-طهارة-السترة-شرط-لصحة-لصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل طهارة السترة شرط للصلاة.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4413,"question":"بول الذكر من الإبل؟","title":"حكم بول الذكر والأنثى من الإبل","answer":"الجواب: الذكر والأنثى كله واحد، كله طاهر.","link":"https://binbaz.org.sa/fatwas/24690/حكم-بول-الذكر-والانثى-من-الابل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بول الذكر من الإبل.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4414,"question":"بالنسبة للهرة والحمار وغيره الأصل فيها النَّجاسة وخفف، وإلا تكون طاهرة؟","title":"هل أبدان الحمار والبغل والهرة طاهرة؟","answer":"الجواب: الأصل فيها الطهارة؛ لأنها من الطوَّافين كما قال النبي ﷺ، إنما ينجس لحمها، لحومها هي النجسة؛ لأنها ذبحت، أما بدنها في حال الحياة فهو طاهر، بخلاف البول والروث فهو نجس، كبني آدم؛ طاهر ولكن روثه فهو نجس، وهكذا الحمار والبغل والهرة أرواثها وأبوالها نجسة، وأما أبدانها فطاهرة.","link":"https://binbaz.org.sa/fatwas/24691/هل-ابدان-الحمار-والبغل-والهرة-طاهرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طهارة الهرة والحمار وغيره.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4416,"question":"إذا ولغ في الإناء يُغسل سبع مرات ويُعفّر بالتراب؟","title":"كيف يتم تطهير الإناء الذي ولغ فيه كلب؟","answer":"الجواب: يُعفّر في التراب في الأولى أفضل، وإن جعلها في غير الأولى فلا بأس.\nس: تكون ثمان يعني؟\nج: باعتبار التراب ثامنة؛ لأنه جزء مُستقل غير الماء.","link":"https://binbaz.org.sa/fatwas/24693/كيف-يتم-تطهير-الاناء-الذي-ولغ-فيه-كلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طهارة الإناء الذي ولغ فيه كلب.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4417,"question":"ولوغ غير الكلب كالخنزير؟","title":"حكم ولوغ حيوان غير الكلب في الإناء","answer":"الجواب: ما ورد فيه شيء، يُعفى عنه، مثلما قال: \"نرد عليها، وترد علينا\"، لكن إذا كان الماء قليلًا يُغسل الغسل العادي، مثل: الأسد والنمر، مثل الذئب إذا ولغ في إناء قليل يُغسل، لكن ما في تحديد بسبعٍ، وإنما مرة أو مرتين أو ثلاثًا حسب الظن أنه أزال أثره.\nس: ولوغ الخنزير ما يكون؟\nج: الخنزير كذلك مثل: الذئب والأسد والنمر، قياسه على الكلب ما هو ظاهر، يعني: مثل بقية الحيوانات.","link":"https://binbaz.org.sa/fatwas/24694/حكم-ولوغ-حيوان-غير-الكلب-في-الاناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الإناء إذا ولغ فيه حيوان غير الكلب كالخنزير.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4418,"question":"الشمس ما تُطهر الأرض؟","title":"هل تُطهر الشمس نجاسة الأرض؟","answer":"الجواب: ما ورد شيء يدل على ذلك، الأصل التَّطهير بالماء، إذا أردت البقعة التي فيها البول تصبّ عليها الماء، تُكاثره بالماء كما أمر النبيُّ ﷺ.","link":"https://binbaz.org.sa/fatwas/24695/هل-تطهر-الشمس-نجاسة-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الشمس تُطهر نجاسة الأرض.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4420,"question":"صفة النَّضح هل هو مجرد؟","title":"ما صفة النَّضح على ما أصابه بول الرضيع؟","answer":"الجواب: الرش على الفرش في المحل، أو يرش الفخذ التي أصابها البولُ، أو الرِّجْل التي أصابها البولُ، يرشه بالماء هكذا، يرشه رشًّا من غير حاجةٍ إلى إسالة الماء.\nس: قول قتادة: ما لم يطعم؟\nج: يعني: إذا تغذَّى بالطعام غُسل مثلما تُغسل الجارية، أما كونه يُعطى شيئًا قليلًا ولا يتغذَّى إلا باللبن؛ ما يجب غسله، يكفي فيه الرش حتى يتغذَّى بالطعام.","link":"https://binbaz.org.sa/fatwas/24697/ما-صفة-النضح-على-ما-اصابه-بول-الرضيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة النَّضح.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4423,"question":"عرق البغال والحمار؟","title":"حكم عرق البغال والحمار ونحوها","answer":"الجواب: العرق لا بأس على الصحيح، عرقها وسؤرها لا بأس؛ لأن الرسول ﷺ كان يركبها عاريةً عليه الصلاة والسلام، وكان يُركبها الناس.\nس: وكذلك إذا ابتلت بالماء؟\nج: كذلك، مثل: الهر: إنه من الطوافين عليكم، لكن قال في أبوالها وأرواثها: نجس مثل بني آدم، بني آدم طاهر، وروثه وبوله نجس.","link":"https://binbaz.org.sa/fatwas/24701/حكم-عرق-البغال-والحمار-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم عرق البغال والحمار، ونحوها.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4424,"question":"إذا لمس الكلب ويده رطبة؟","title":"ما يفعل من لمس الكلب ويده رطبة؟","answer":"الجواب: الظاهر مثل غيره يغسلها، الصواب أنه نجس، ولهذا قال النبيُّ ﷺ: طهور الإناء إذا ولغ فيه الكلبُ غسله سبع مرات، أما إذا لمسه وهو يابس فلا يضرّ.\nس: يغسل يده سبعًا؟\nج: هذا هو الأظهر؛ إلحاقًا له بالولوغ.","link":"https://binbaz.org.sa/fatwas/24702/ما-يفعل-من-لمس-الكلب-ويده-رطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم إذا لمس الكلب ويده رطبة.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4433,"question":"حكم الماء الراكد في الشمس؟","title":"حكم الماء المشمّس والبول في الماء الراكد","answer":"الجواب: ما في بأس، الشمس لا بأس، الماء المشمس فيه أخبار باطلة، ما هي صحيحة. كذلك البول في الماء الراكد يُنهى عنه، مثلما نهى النبيُّ ﷺ في حديث أبي هريرة عن البول في الماء الراكد؛ لأنَّ الماء الراكد يتأثر، فإذا بال فيه الناسُ تتابعت عليه الأبوال، وقد يتغير، فيكون نجسًا، فلهذا سدَّ النبي ﷺ الذَّريعة، ونهى عن البول في الماء الراكد؛ لئلا ينجر ذلك إلى تنجيسه وتقذيره.","link":"https://binbaz.org.sa/fatwas/24711/حكم-الماء-المشمس-والبول-في-الماء-الراكد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الماء الراكد في الشمس.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":4434,"question":"إذا كان في الإنسان بولٌ لا يعلم موضعه؟","title":"حكم من أصابه بولٌ لا يعلم موضعه","answer":"الجواب: يتحرى ويغسل ما أصابه، يتحرى موضعَه من جسده أو من ثوبه ويغسل، فإن خفي عليه يغسل الثوبَ كله والحمد لله.\nس: ما يكفي الرَّش؟\nج: لا، البول ما يكفي فيه الرش، هذاك المذي وبول الصبي الصغير الذي ما أكل الطعام يكفي فيه الرش.","link":"https://binbaz.org.sa/fatwas/24712/حكم-من-اصابه-بول-لا-يعلم-موضعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من أصابه بولٌ لا يعلم موضعه.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4538,"question":"وحمل ابنه وعليه نجاسة عالم بها، لكنه بينه وبينه حائل؟","title":"حكم حمل الطفل في الصلاة وعليه نجاسة","answer":"الجواب: الأقرب -والله أعلم- أنه لا يحمله عالمًا بالنجاسة، لا يحمله عملًا بالأصل أن المصلِّي لا يحمل النَّجاسة، لكن إذا لم يدر أو علم أنه طاهر فالحمد لله، أو ما يدري فالحمد لله يحمل، حمل أمامة على أنها طاهرة، أو لم يدرِ عن حالها عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24818/حكم-حمل-الطفل-في-الصلاة-وعليه-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حمل الطفل في الصلاة وعليه نجاسة.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4542,"question":"السؤال.يُعتبر التراب مُطهِّرًا للنَّجاسات؟","title":"هل يُعتبر التراب مُطهِّرًا للنَّجاسات؟","answer":"الجواب: إذا حكَّها وأزالها بالكلية، حكَّها ولم يبقَ فيها شيء؛ مطهر لها.","link":"https://binbaz.org.sa/fatwas/24822/هل-يعتبر-التراب-مطهرا-للنجاسات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُعتبر التراب مُطهِّرًا للنَّجاسات.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":4619,"question":"لو علم أنَّ في سراويله نجاسةً ثم استمرَّ في صلاته وهو إمام؟","title":"حكم الصلاة إذا علم الإمام أن في ثوبه نجاسة","answer":"الجواب: يُعيد ولا يُعيدون؛ لأنهم ما علموا، والواجب أن يستخلف.","link":"https://binbaz.org.sa/fatwas/24909/حكم-الصلاة-اذا-علم-الامام-ان-في-ثوبه-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا علم الإمام أن في ثوبه نجاسة في الصلاة.mp3","categories":["النجاسات وإزالتها","صلاة الجماعة"]},{"id":5138,"question":"يقول هذا السائل: يوجد لدينا في المستشفى مياه مجارٍ مُكررة، ونتعرض لتلك المياه في كثيرٍ من الأماكن من جراء ريِّ الحدائق، وقد نتعرض ولو لرذاذٍ منها، فهل تلك المياه نجسة تُبْطِل الوضوء؟ وهل الأشجار التي تُروى منها يجوز أكلُ ثمارها أم لا؟ أفيدونا جزاكم الله خيرًا.","title":"ما حكم مياه المجاري المكررة؟","answer":"الجواب: إذا كانت هذه المياه قد كُررت حتى ذهبتْ منها رائحةُ النَّجاسة وطعم النَّجاسة ولونها، وصارت مياهًا عذبةً طيبةً سليمةً؛ فلا حرج في ذلك، ويكون لها حكم الطَّهارة، وما يُصيب الناسَ منها لا يضرُّ، والشجر الذي يُسقى بها لا يضرُّ، وثماره لا بأس به. أمَّا إذا كانت لا؛ آثارُ النجاسة باقيةً فيها فلا تُستعمل، لا في الأشجار، ولا في غيرها، بل تُزال إلى جهةٍ أخرى لا تُؤذي المسلمين. أمَّا إذا كانت كُررت تكريرًا كاملًا وزالت منها آثارُ النَّجاسة، لا لونًا، و لا طعمًا، ولا ريحًا، فالحمد لله.","link":"https://binbaz.org.sa/fatwas/30053/ما-حكم-مياه-المجاري-المكررة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 74.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":5145,"question":"يقول هذا السائل يا سماحة الشيخ: أثناء إجراء بعض العمليات تبتل الملابس -حتى الداخلية- والجلد بالدم والبول، وقد يتكرر الأمر خلال اليوم، فهل على الطبيب الغُسل عند ذلك أم يُجزئ الوضوء؟","title":"حكم ما يصيب الطبيب في جلده وثوبه أثناء العمليات","answer":"الجواب: عليه أن يغسل ما أصابه، أو يبدّل الثياب بثياب سليمة، وما أصاب البدن أصاب الرِّجْل، أو اليد، أو نحوه، يغسله، وما عليه غُسل.  عليه أن يَغْسِلَ ما أصابه فقط: ما أصاب البدن، أو ما أصاب الثوب إذا كان يُصلي فيه، أو يبدّله بغيره ويُصلي بثوبٍ سليم، وما أصاب الرِّجْل أو الرأس أو الوجه يُغسل.","link":"https://binbaz.org.sa/fatwas/30060/حكم-ما-يصيب-الطبيب-في-جلده-وثوبه-اثناء-العمليات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 81.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":5617,"question":"هل يُعفى عن يسير الدم في الثياب؟","title":"ما حَدُّ الدم اليسير في الثياب؟ وما حكمه؟","answer":"الجواب: اليسير يُعفى عنه، يسير الدم نعم. س: حدّه؟ ج: ما يعتقده صاحبه خفيفًا، على حسب ما يراه صاحبه، يستفحشه. س: لا فرق بين المسفوح وغيره؟ ج: مطلقًا، نعم، على حسب ما يراه هو.[1]","link":"https://binbaz.org.sa/fatwas/31600/ما-حد-الدم-اليسير-في-الثياب-وما-حكمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 057.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":5618,"question":"سِنّ الميتة نجس؟","title":"هل عَظْم الميتة طاهر أم نجس؟","answer":"الجواب: السِّن ما تدخله النجاسة، العَظْم.   س: تقييده بمُذكاةٍ هنا؟ ج: هذا مقصوده أنها تدخله النجاسة، إذا كانت ميتة تبعها جسمها، ولكن الأقرب أنه لا تدخله النَّجاسة.[1]","link":"https://binbaz.org.sa/fatwas/31601/هل-عظم-الميتة-طاهر-ام-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 058.mp3","categories":["قضايا المرأة","النجاسات وإزالتها"]},{"id":5852,"question":"هل المني طاهر، أم نجس؟ وهل يكفي فركه إن كان يابسًا، والغسل إذا كان رطبًا؟","title":"هل المني طاهر أم نجس؟","answer":"الجواب:  المني على الصحيح طاهر، وهو أصل الإنسان، والنبي ﷺ قالت عائشة: ربما غسله، وربما فركه، قالت: كنت أفركه من ثوبه، كنت أحكه يابسًا من ثوبه؛ فدل ذلك على أنه طاهر، إذ لو كان نجسًا؛ لغسل، لما اكتفي به بالحك، والتنظيف بإزالته بدون ماء، دل على طهارته؛ ولأنه أصل الإنسان؛ فالإنسان طاهر، وأصله طاهر، أصله التراب، والتراب طاهر، ثم المني بعد ذلك فهو طاهر، والإنسان طاهر.","link":"https://binbaz.org.sa/fatwas/1183/هل-المني-طاهر-ام-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_179.mp3","categories":["الآداب والأخلاق","النجاسات وإزالتها"]},{"id":5853,"question":"أحد الإخوة جاء بقصاصة مصورة لبعض الجرئد اليومية، ومكتوب في ركنها ركن الفتاوى: ما حكم الإسلام في سماع الموسيقى؟ وهل سمعها، أو تعليمها حلال، أو حرام؟ الإجابة: الإنسان عاطفي بطبعه، والشرائع السماوية لا تقتل في الإنسان غرائزه، ولا تميت فيه عاطفة، ولكن مهمتها في هذه الناحية كبح الجماح، والحد من الاندفاع الذي يخرج الإنسان عن الحد اللائق، وظل يتكلم في هذا الموضوع  إلى أن قال: والاستماع إلى الموسيقى على هذا الوجه مباح، ومشروع أخذًا بما روته السنة من أن الرسول ﷺ مر على قوم يعزفون بالدف، ويعزفون بالموسيقى، ويرددون الأغاني في مناسبة عرس، وكان في صحبته عمر، فلما أراد عمر منعهم، قال -صلوات الله عليه-: دعهم فإن هذا يفرق بين النكاح، والسفاح. فما رأي سماحتكم؟","title":"حكم سماع الغناء وآلات اللهو","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله، وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أن هذه الفتوى غلط من قائلها، ولا ريب أن سماع الموسيقى، وآلات الملاهي من المنكرات، وقد حكى بعض أهل العلم: إجماع أهل العلم على أن سماع الغناء، وآلات اللهو إذا اجتمعا فهو من المحرمات بالإجماع.  وقد دلت السنة على أن المعازف من المحرمات التي يستحلها الناس في آخر الزمان، ثبت عنه ﷺ أنه قال: ليكونن من أمتي أقوام يستحلون الحر، والحرير، والخمر، والمعازف يعني في آخر الزمان، رواه البخاري في الصحيح معلقًا مجزومًا، والحرّ هو الفرج الحرام، يعني: الزنا، والخمر معروف، والمعازف هي آلات الملاهي، والحرير معروف، محرم على الرجال دون النساء، فأخبر النبي ﷺ أنه يكون في آخر الزمان قوم يستحلون هذا وهذا، يستحلون الزنا، ويستحلون لبس الحرير من الرجال، ويستحلون الخمر، ويستحلون المعازف، وهي الغناء، وآلات الملاهي، ولا شك أن الموسيقى من آلات الملاهي، ومن المطربات. والذي أحله النبي ﷺ هو ما يتعلق بالنساء في العرس، الغناء العادي الذي لا يدعو إلى الفساد؛ بل غناء الناس فيما بينهم مع دف للنساء في الأعراس، أو من الجواري الصغار في الأعياد، هذا هو الذي جاء عن النبي ﷺ حله، أما للرجال فلا. والمقصود: أنه ﷺ أحل أيضًا للحبشة اللعب في المسجد بآلات السلاح بالدرقة، والسيوف، والرماح التي تقذف، وأشباه ذلك من باب التدرب على الحرب، وآلات الملاهي، ولما أراد عمر أن ينكر عليهم ذلك قال: دعهم حتى تعلم اليهود أن في ديننا فسحة وفي قصة الجواري: دعهم فإن لكل قوم عيدًا. فالمقصود: أن التدرب على آلات الحرب، كالسلاح، ورمي الدرق، واتقاء سيوف الدرق، وما أشبه ذلك؛ هذا من الأمور المطلوبة شرعًا للإعداد للقتال، والتأهب للقتال، والتدرب على آلات القتال في المسجد، وغيره. أما سماع آلات الملاهي من الموسيقى، أو العود، أو الكمان، أو غير هذا من أنواع آلات الملاهي، فهذا لا شك أنه منكر، ومن أسباب ضعف الإيمان، ومن أسباب موت الغيرة في القلوب، ولا شك أن الذي أحله النبي ﷺ إنما هو شيء يتعلق بالنساء، والأعراس حتى يعلم الفرق بين السفاح، والنكاح، فالسفاح يكون بالخلوة، والفواحش، والنكاح يكون بالعلن، ويكون بالدف للنساء، والغناء العادي للنساء، لا فيما يتعلق بالأغاني التي تدعو إلى الفواحش، والمنكرات، والخمر، وغير ذلك، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1195/حكم-سماع-الغناء-والات-اللهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_191.mp3","categories":["الشعر والأغاني","النجاسات وإزالتها"]},{"id":5857,"question":"هل المني طاهر، أم نجس؟ وهل يكفي فركه إن كان يابسًا، والغسل إذا كان رطبًا؟","title":"هل المني طاهر أم نجس؟","answer":"الجواب:  المني على الصحيح طاهر، وهو أصل الإنسان، والنبي ﷺ قالت عائشة: ربما غسله، وربما فركه، قالت: كنت أفركه من ثوبه، كنت أحكه يابسًا من ثوبه؛ فدل ذلك على أنه طاهر، إذ لو كان نجسًا؛ لغسل، لما اكتفي به بالحك، والتنظيف بإزالته بدون ماء، دل على طهارته؛ ولأنه أصل الإنسان؛ فالإنسان طاهر، وأصله طاهر، أصله التراب، والتراب طاهر، ثم المني بعد ذلك فهو طاهر، والإنسان طاهر.","link":"https://binbaz.org.sa/fatwas/1183/هل-المني-طاهر-ام-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_179.mp3","categories":["الآداب والأخلاق","النجاسات وإزالتها"]},{"id":5858,"question":"أحد الإخوة جاء بقصاصة مصورة لبعض الجرئد اليومية، ومكتوب في ركنها ركن الفتاوى: ما حكم الإسلام في سماع الموسيقى؟ وهل سمعها، أو تعليمها حلال، أو حرام؟ الإجابة: الإنسان عاطفي بطبعه، والشرائع السماوية لا تقتل في الإنسان غرائزه، ولا تميت فيه عاطفة، ولكن مهمتها في هذه الناحية كبح الجماح، والحد من الاندفاع الذي يخرج الإنسان عن الحد اللائق، وظل يتكلم في هذا الموضوع  إلى أن قال: والاستماع إلى الموسيقى على هذا الوجه مباح، ومشروع أخذًا بما روته السنة من أن الرسول ﷺ مر على قوم يعزفون بالدف، ويعزفون بالموسيقى، ويرددون الأغاني في مناسبة عرس، وكان في صحبته عمر، فلما أراد عمر منعهم، قال -صلوات الله عليه-: دعهم فإن هذا يفرق بين النكاح، والسفاح. فما رأي سماحتكم؟","title":"حكم سماع الغناء وآلات اللهو","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله، وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أن هذه الفتوى غلط من قائلها، ولا ريب أن سماع الموسيقى، وآلات الملاهي من المنكرات، وقد حكى بعض أهل العلم: إجماع أهل العلم على أن سماع الغناء، وآلات اللهو إذا اجتمعا فهو من المحرمات بالإجماع.  وقد دلت السنة على أن المعازف من المحرمات التي يستحلها الناس في آخر الزمان، ثبت عنه ﷺ أنه قال: ليكونن من أمتي أقوام يستحلون الحر، والحرير، والخمر، والمعازف يعني في آخر الزمان، رواه البخاري في الصحيح معلقًا مجزومًا، والحرّ هو الفرج الحرام، يعني: الزنا، والخمر معروف، والمعازف هي آلات الملاهي، والحرير معروف، محرم على الرجال دون النساء، فأخبر النبي ﷺ أنه يكون في آخر الزمان قوم يستحلون هذا وهذا، يستحلون الزنا، ويستحلون لبس الحرير من الرجال، ويستحلون الخمر، ويستحلون المعازف، وهي الغناء، وآلات الملاهي، ولا شك أن الموسيقى من آلات الملاهي، ومن المطربات. والذي أحله النبي ﷺ هو ما يتعلق بالنساء في العرس، الغناء العادي الذي لا يدعو إلى الفساد؛ بل غناء الناس فيما بينهم مع دف للنساء في الأعراس، أو من الجواري الصغار في الأعياد، هذا هو الذي جاء عن النبي ﷺ حله، أما للرجال فلا. والمقصود: أنه ﷺ أحل أيضًا للحبشة اللعب في المسجد بآلات السلاح بالدرقة، والسيوف، والرماح التي تقذف، وأشباه ذلك من باب التدرب على الحرب، وآلات الملاهي، ولما أراد عمر أن ينكر عليهم ذلك قال: دعهم حتى تعلم اليهود أن في ديننا فسحة وفي قصة الجواري: دعهم فإن لكل قوم عيدًا. فالمقصود: أن التدرب على آلات الحرب، كالسلاح، ورمي الدرق، واتقاء سيوف الدرق، وما أشبه ذلك؛ هذا من الأمور المطلوبة شرعًا للإعداد للقتال، والتأهب للقتال، والتدرب على آلات القتال في المسجد، وغيره. أما سماع آلات الملاهي من الموسيقى، أو العود، أو الكمان، أو غير هذا من أنواع آلات الملاهي، فهذا لا شك أنه منكر، ومن أسباب ضعف الإيمان، ومن أسباب موت الغيرة في القلوب، ولا شك أن الذي أحله النبي ﷺ إنما هو شيء يتعلق بالنساء، والأعراس حتى يعلم الفرق بين السفاح، والنكاح، فالسفاح يكون بالخلوة، والفواحش، والنكاح يكون بالعلن، ويكون بالدف للنساء، والغناء العادي للنساء، لا فيما يتعلق بالأغاني التي تدعو إلى الفواحش، والمنكرات، والخمر، وغير ذلك، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1195/حكم-سماع-الغناء-والات-اللهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_191.mp3","categories":["الشعر والأغاني","النجاسات وإزالتها"]},{"id":5862,"question":"ما الفرق بين الدف، والطنبور؟","title":"الفرق بين الدف والطنبور","answer":"الجواب: معروف الطنبور، لكن بعض أهل العلم قال: إنه الطبل، وعلى كل حال فالدف مباح، وما سواه غير مباح، الدف للنساء هو المباح، والدف نوع يتخذ من الطيلان، له وجه واحد، لا يكون فيه حلق، ولا يكون فيه حديد تضربه النساء.   وأما الطنبور فجاء الحديث في النهي عنه، وهكذا الطبل، وهكذا سائر الملاهي، كلها محرمة.","link":"https://binbaz.org.sa/fatwas/1196/الفرق-بين-الدف-والطنبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_192.mp3","categories":["الشعر والأغاني","النجاسات وإزالتها"]},{"id":5955,"question":"هل تطهر الأرض ثوب المرأة، وحذاء المسلم؟","title":"كيفية تطهير ذيل ثوب المرأة والنعل","answer":"الجواب: نعم، إذا أصاب ثوبها نجاسة، أو ذيلها نجاسة، أو النعل، ثم مر على الأرض الطيبة؛ طهرت، يحكه بالأرض الطيبة، ويكفي ذلك.","link":"https://binbaz.org.sa/fatwas/1324/كيفية-تطهير-ذيل-ثوب-المراة-والنعل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_293.mp3","categories":["النجاسات وإزالتها"]},{"id":6194,"question":"قد يبول الأطفال أحيانًا على فرش البيت، فهل يكتفى بوضع سجادة للصلاة فوق الفرش؟","title":"حكم الصلاة على سجادة تحتها فراش نجس","answer":"الجواب: إذا وضع على الفراش الذي فيه بول سجادة، وصلى عليها؛ لا بأس، وإذا غسل الموضع الذي أصابه البول، وصب عليه الماء حتى يكاثره؛ تطهر المكان، وإذا وضع السجادة، أو بساط طاهر على بسط نجسة؛ كفى ذلك.","link":"https://binbaz.org.sa/fatwas/1666/حكم-الصلاة-على-سجادة-تحتها-فراش-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_545.mp3","categories":["الشعر والأغاني","النجاسات وإزالتها"]},{"id":6435,"question":"حدث أحد المشايخ في التلفزيون يوم الجمعة بتاريخ 12/6 يقول: إن الإنسان إذا قضى الحاجة، وفشَّر على ملابسه شيء من البول ليس فيه حرام، بل إنه مكروه أفيدونا، جزاكم الله خير الجزاء؟","title":"حكم وقوع رذاذ البول على الجسم أو الثوب","answer":"الجواب: ما أظن أن يقول هذا عالم إنسان، هذا جاهل، ما يقول هذا عالم، رشاش البول نجس إذا أصاب ثيابه، رذاذ البول وجب غسل البول، وإذا أصاب رجله غسلها، وهكذا إذا أصاب شيئاً آخر، النبي  يقول: استنزهوا من البول، فإن عامة عذاب القبر منه ويقول: أكثر عذاب القبر من البول هكذا صح عنه، عليه الصلاة والسلام. وفي الصحيحين عن ابن عباس -رضي الله عنهما- قال: مر النبي ﷺ على قبرين، فقال: إنهما ليعذبان، وما يعذبان في كبير ثم قال: بلى، أما أحدهما: فكان لا يستتر من البول وفي رواية: لا يتنزه من البول، وأما الآخر: فكان يمشي بالنميمة فدل على أن عدم التنزه من البول من أسباب العذاب، وهكذا المشي بالنميمة بين الناس، يتكلم يروح بين الناس يقول: فلان قال فيكم كذا، فلان قال فيك كذا، يسعى بين الناس بالنميمة حتى يشوش عليهم، وحتى يثير بينهم الشحناء، والعداوة -والعياذ بالله- هذه من الكبائر العظيمة.  فالبول يجب التنزه منه، ولا يجوز التساهل فيه، إذا علم أنه طار من بوله شيء على ثيابه، أو على إنائه، في وسط إنائه، أو على رجله؛ يصب عليه الماء، هذا بإجماع المسلمين ليس فيه نزاع.","link":"https://binbaz.org.sa/fatwas/2177/حكم-وقوع-رذاذ-البول-على-الجسم-او-الثوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_803.mp3","categories":["النجاسات وإزالتها"]},{"id":6448,"question":"حدث أحد المشايخ في التلفزيون يوم الجمعة بتاريخ 12/6 يقول: إن الإنسان إذا قضى الحاجة، وفشَّر على ملابسه شيء من البول ليس فيه حرام، بل إنه مكروه أفيدونا، جزاكم الله خير الجزاء؟","title":"حكم وقوع رذاذ البول على الجسم أو الثوب","answer":"الجواب: ما أظن أن يقول هذا عالم إنسان، هذا جاهل، ما يقول هذا عالم، رشاش البول نجس إذا أصاب ثيابه، رذاذ البول وجب غسل البول، وإذا أصاب رجله غسلها، وهكذا إذا أصاب شيئاً آخر، النبي  يقول: استنزهوا من البول، فإن عامة عذاب القبر منه ويقول: أكثر عذاب القبر من البول هكذا صح عنه، عليه الصلاة والسلام. وفي الصحيحين عن ابن عباس -رضي الله عنهما- قال: مر النبي ﷺ على قبرين، فقال: إنهما ليعذبان، وما يعذبان في كبير ثم قال: بلى، أما أحدهما: فكان لا يستتر من البول وفي رواية: لا يتنزه من البول، وأما الآخر: فكان يمشي بالنميمة فدل على أن عدم التنزه من البول من أسباب العذاب، وهكذا المشي بالنميمة بين الناس، يتكلم يروح بين الناس يقول: فلان قال فيكم كذا، فلان قال فيك كذا، يسعى بين الناس بالنميمة حتى يشوش عليهم، وحتى يثير بينهم الشحناء، والعداوة -والعياذ بالله- هذه من الكبائر العظيمة.  فالبول يجب التنزه منه، ولا يجوز التساهل فيه، إذا علم أنه طار من بوله شيء على ثيابه، أو على إنائه، في وسط إنائه، أو على رجله؛ يصب عليه الماء، هذا بإجماع المسلمين ليس فيه نزاع.","link":"https://binbaz.org.sa/fatwas/2177/حكم-وقوع-رذاذ-البول-على-الجسم-او-الثوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_803.mp3","categories":["النجاسات وإزالتها"]},{"id":7674,"question":"ونبدأ يا سماحة الشيخ برسالة المستمع فهد عبد الوهاب الخميس من الزلفي، يقول: إلى فضيلة الشيخ: عبد العزيز بن عبد الله بن باز ، السلام عليكم ورحمة الله وبركاته، حفظكم الله، آمين: إنسان صلى جماعة فلما خرج من المسجد وجد معه منديل فيه دم من بشرته فقذفه ورجع يعيد الصلاة فوجد جماعةً فصلى معهم، هل إذا حصل مثل هذا عليه إعادة الصلاة أم لا؟ أفيدونا جزاكم الله خير، ولكم منا جزيل الشكر، ونرجو لكم التوفيق إن شاء الله تعالى.","title":"حكم صلاة من كان حامل النجاسة","answer":"الجواب: الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nإذا صلى الإنسان رجلاً كان أو امرأة، ثم بعد الفراغ وجد في منديله دماً، أو في ثوبه دماً، أو في سراويله دماً، أو غير ذلك من النجاسات، فإن الصواب: أنه لا يعيد الصلاة، صلاته تجزي وتصح، هذا هو الصواب من أقوال العلماء، أنه لا إعادة عليه وصلاته صحيحة، وإن كان قد علم ذلك سابقاً ثم نسيه حتى صلى، كذلك صلاته صحيحة، وعليه أن يبادر بغسل ذلك، وتنظيف ثوبه من ذلك، والحجة في ذلك أن الرسول ﷺ صلى وعليه نعلان فأخبره جبرائيل أن فيهما أذى، فخلعهما ولم يعد أول الصلاة، فدل ذلك على أنه لو كملها ما عاد، فالمقصود أن من كان في ثوبه نجاسة ما علم بها حتى فرغ، أو في سراويله، أو في إزاره، أو في عمامته، أو في منديله، أو في خفه ونعله ولم يعلم حتى فرغ فصلاته صحيحة، هذا هو الصواب الذي عليه المحققون من أهل العلم، ولا إعادة عليه. نعم.\nلكن هنا شيء آخر قد يظنه بعض الناس مثل هذا، وهو إذا صلى يحسب أنه متوضئ، أو يحسب أنه قد تطهر من الجنابة، ثم بان أن عليه جنابة، أو أنه ما توضأ هذا يعيد بإجماع المسلمين، هذا عليه أن يعيد؛ لأنه صلى بغير طهارة بالحدث، هذا ما هو من جنس النجاسة، هذا إذا صلى مثلاً يحسب أنه على وضوء، أو يحسب أنه قد اغتسل من الجنابة، ثم لما صلى ذكر أن عليه جنابة، أو أنه ما توضأ أنه محدث، هذا عليه أن يتوضأ وأن يغتسل من الجنابة إذا كان عليه جنابة ثم يعيد صلاته، وإن كان إمام لا يعيد المأمومون، إذا ما درى إلا بعد الصلاة يعيد هو أما المأمومون فلا يعيدون إذا كان ما انتبه إلا بعد الصلاة، هذه مسألة قد تخفى على بعض الناس، وقد تشتبه بمسألة النجاسة والحكم يختلف. نعم.","link":"https://binbaz.org.sa/fatwas/4873/حكم-صلاة-من-كان-حامل-النجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04001.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]},{"id":7753,"question":"سؤاله هذا يقول فيه: إذا سقط في ثوب إنسان نجاسة وهو لا يدري مكان النجاسة فماذا يفعل؟","title":"حكم من أصابت ثوبه نجاسة ولم يعلم مكانها","answer":"الجواب: إذا كان لا يدري إن كان يمكن التحري يتحرى حتى يغسل المحل اللي تحراه، فإن كان لا يدري ولا يغلب على ظنه شيء يغسله كله يلزمه غسله كله، أما إذا ظنها في محل، تحراها في محل معين منه غسل المحل المعين الذي تحراه في طرفه الأسفل، في كمه، في أي محل يتحراه. نعم.\nالمقدم: أحسنتم أثابكم الله.","link":"https://binbaz.org.sa/fatwas/4953/حكم-من-اصابت-ثوبه-نجاسة-ولم-يعلم-مكانها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_043/04305.mp3","categories":["النجاسات وإزالتها"]},{"id":8588,"question":"لها سؤال آخر الأخت (س. م. ع) من المدينة المنورة، تقول: ما حكم من وقع على ملابسها نجاسة أثناء تواجدها في مكان عام مثل المدرسة أو المستشفى وحضرت صلاة العصر وصلت ولم تعد إلى منزلها إلا بعد حضور صلاة المغرب، فأعادت صلاة العصر بعد صلاة المغرب، أفيدونا أفادكم الله؟","title":"حكم من وقع على ثوبه نجاسة ويريد الصلاة","answer":"الجواب: إذا وقع على ثياب الإنسان نجاسة وهو يعلم أنها نجاسة، ليس عن وسواس، بل يعلم أنها نجاسة فليس له أن يصلي حتى يغسلها، إذا كان عنده ماء، إذا استطاع الماء، ليس له أن يصلي حتى يغسل النجاسة، أما إن كان ظن وليس بجزم وإنما يظن أنها نجاسة ووسواس منه، هذا لا عمل عليه وليس فيه نجاسة، والأصل الطهارة، فإذا أصاب ثوب المرأة في المدرسة أو في أي مكان شيء رطب أو سقط عليها شيء فيه رطوبة فلا تحمله على النجاسة، الأصل الطهارة حتى تعلم أنه نجس، فإذا علمت ذلك يقيناً غسلته، والحمد لله.\nفإن لم تجد ماء بأن كانت في محل لا ماء فيه ولا تستطيع الخروج وتخشى خروج الوقت صلت ولا حرج عليها في ذلك، صلاتها صحيحة، فإذا استمرت ولم تصل إلا بعد الغروب إذا أحست بهذا وقت العصر، ولكنها أخرت حتى غابت الشمس فصلت المغرب ثم صلت العصر فهذا فيه تفصيل: إن كانت حين صلت المغرب قبل صلاة العصر ناسية أنها نجاسة أو شاكة فيها ثم علمت بعد ذلك فلا شيء عليها تعيد العصر والحمد لله؛ لأنها حين صلت المغرب ما عندها يقين أن صلاة العصر غير صحيحة، أما إن كانت ما صلت العصر بالكلية ثم صلت المغرب قبلها، هذا لا يصح لابد من أن تصلي العصر أول ثم تصلي المغرب، لكن إذا صلت العصر، ثم علمت أن في ثوبها نجاسة فإن صلاتها صحيحة، ولا تعيد الصلاة؛ لأن المسلم إذا صلى وفي ثوبه نجاسة جاهلاً بها لا يعلمها أو ناسياً لها فصلاته صحيحة؛ لأن النبي ﷺ صلى ذات يوم وفي نعليه أذى فأخبره جبرائيل عليه الصلاة والسلام بذلك، فخلع نعليه ولم يستأنف الصلاة ولم يعد أولها عليه الصلاة والسلام، فدل ذلك على أن الإنسان إذا صلى ثم علم أن في ثوبه نجاسة أو على بدنه نجاسة فلا إعادة عليه، ليس عليه إعادة، لأنه لم يعلم ذلك إلا بعد الصلاة.\nوالخلاصة: أن الإنسان إذا صلى المغرب أو العشاء أو غيرهما ثم ذكر أن عليه صلاة فإنه يأتي بالصلاة التي عليه ولا يعيد ما صلى، أما إذا تعمد أن يصلي المغرب وعليه صلاة العصر وهو يدري أن عليه صلاة العصر، أو تعمد يصلي العشاء وعليه صلاة المغرب قد علم ذلك هذا لا يجوز؛ لأن الترتيب واجب، إما إذا كان حين صلى المغرب أو العشاء قبل العصر أو قبل المغرب ناسياً أن عليه صلاة، أو جاهلاً أن عليه صلاة، فصلاته صحيحة، وليس عليه أن يعيد إلا الصلاة التي ثبت لديه أنها غير صحيحة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6667/حكم-من-وقع-على-ثوبه-نجاسة-ويريد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20906.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":8650,"question":"هذه رسالة وردتنا من السائل محمد عبد الستار محمد إبراهيم ، مصري الجنسية مقيم في الرياض، يقول: سؤالي هو: أنه ينزل مني بعد البول سائل أبيض اللون مذي، فما حكم وضوئي والطريقة الصحيحة في هذا الوضوء، علماً بأنني أعصر ذكري بعد الاستنجاء، وقد قال لي بعض الإخوة: إن هذا غير صحيح وغير طيب من الناحية الصحية، فكنت أضع ورق مناديل وأنتظر بعض الوقت، ولكن أحياناً أكون في الشارع ويؤذن للصلاة وأكون في حاجة لدخول الحمام للبول لكنني أحبس نفسي وأتوضأ مباشرة وأصلي وأخشى أن تكون هذه الصلاة غير كاملة، فأفيدوني أفادكم الله؟","title":"الحذر من الوساوس عند البول وحكم المذي والمني","answer":"الجواب: لا ينبغي التكلف في هذا الأمر، وعصر الذكر فيه خطر عظيم وهو من أسباب السلس، ومن أسباب الوساوس، ولكن متى خرج البول تستنجي والحمد لله، أو تستجمر والحمد لله الاستجمار الشرعي، أما عصر الذكر والحرص على محاولة أن يخرج شيء هذا غلط ولا يجوز، وهو من أسباب الابتداء بالوسوسة وسلس البول، فينبغي لك أن تحذر هذا، متى انقطع البول تستنجي بالماء أو تستجمر بالحجارة ونحوها ثلاث مرات فأكثر حتى يزول الأذى ويكفي.\nوما يخرج من الماء الأبيض بعد البول وهو المذي أو الودي كله في حكم البول سواءً كان مذياً أو ودياً تستنجي منه، لكن إذا كان مذياً وهو الذي يخرج بأسباب الشهوة، عند تحرك الشهوة يكون مذي وهو ماء لزج معروف، فهذا تغسل معه الذكر والأنثيين جميعاً، تغسل الذكر والأنثيين كماء جاءت به السنة، أما الماء الأبيض غير المذي وهو الودي فهذا حكمه حكم البول، تغسل أطراف الذكر الذي أصابه البول ويكفي كذلك والحمد لله.\nولكن نحذرك بأن تبتعد عن عصر الذكر؛ لأن هذا يسبب مشاكل يسبب السلسل ويسبب الوساوس، تترك هذا ولا تعود إليه إن شاء الله. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6793/الحذر-من-الوساوس-عند-البول-وحكم-المذي-والمني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21308.mp3","categories":["النجاسات وإزالتها"," الوسواس بأنواعه"]},{"id":8666,"question":"غسل الملابس ومسح البلاط والمشي على السجاد الذي تبول عليه الأطفال؟الشيخ: غسل الملابس، وايش بعد؟المقدم: ومسح البلاط؟","title":"حكم المشي على السجاد الذي تبول عليه الأطفال للمتوضئ","answer":"الجواب: غسل الملابس تقدم هذا لا يضر، ومسح البلاط كذلك، إن كان فيه نجاسة تغسل ما أصاب يدها، إذا كانت الملابس نجسة تغسلها ثم تغسلها غسلاً يزيل أثر النجاسة به حسب الظن، تغسله مرتين ثلاث بالعصر تطهر وتطهر يدها مع ذلك، وغسل البلاط كذلك إن كان فيه نجاسة، تغسل البلاط ثم تغسل يديها من أثر البلاط غسلاً يزيل أثر النجاسة عن البلاط وعن يدها، مرتين تصب الماء مرتين ثلاث أربع حسب ما تظن أنه زال أثر النجاسة، وايش بعد غسل البلاط؟\nالمقدم: المشي على السجاد الذي سبق وتبول عليه الأطفال؟\nالشيخ: هذا فيه تفصيل: إن كان السجاد يابس والرجل يابسة أو في الكنادر ما تضر، فإن كانت الرجل رطبة أو الفراش رطب من البول تغسل رجلها إذا وطئت البول أو وطئت الفراش الذي فيه البول تغسل رجلها في محل آخر طاهر وينتهي الأمر.","link":"https://binbaz.org.sa/fatwas/6808/حكم-المشي-على-السجاد-الذي-تبول-عليه-الاطفال-للمتوضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21413.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":8670,"question":"ملامسة ملابس الطفل المبتلة بالبول؟","title":"حكم لمس ملابس الطفل المبتلة بالبول بعد الوضوء","answer":"الجواب: إذا كان الطفل ملابسه مبتلة بالبول لا تلمسها فإن لمستها تغسل يدها، تغسل ما أصاب يدها من البول، والوضوء لا ينتقض.","link":"https://binbaz.org.sa/fatwas/6804/حكم-لمس-ملابس-الطفل-المبتلة-بالبول-بعد-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21409.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":9434,"question":"يسأل أيضاً ويقول: ما حكم الشرع في أن يترك الرجل فراشه أو غطاء نومه لا يغسلهما عن النجاسات، بل يتركهما حتى ييبسا وهل تنجس الثياب إذا جلس عليها أحد من الناس؟","title":"حكم ترك الفرش والملابس دون تغسيل إذا أصابتها نجاسة","answer":"الجواب: ينبغي إذا أصاب الفراش نجاسة أن يغسل، وهكذا الرداء يغسل، وكذا الوسائد، لأن الإنسان قد يأتي إليها وعليه ملابس رطبة أو جسمه رطب فيتنجس بها، فالواجب أن تغسل وتطهر حتى إذا وطء عليها وأزيلت الرطبة أو جلس عليها بثوب رطب يسلم من شرها، أما إذا بقيت بالنجاسة ثم جلس عليها وهو رطب تنجس، فلا ينبغي هذا بل يجب على المؤمن أن يحذر ذلك، وأن يغسل ما يحتاج إليه من وطاء أو غطاء أو غير ذلك مما ينتفع به، فإذا كان قد اخلولق ولا حاجة إليه يلقى مع القمامة، أما يستعمله وهو نجس لا، يطهره أولاً ثم يستعمله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7603/حكم-ترك-الفرش-والملابس-دون-تغسيل-اذا-اصابتها-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23905.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":9730,"question":"السؤال الثالث في رسالة الأخ محمد بكري يقول فيه: أحيانًا تكون ثياب ابني الصغير مبللة بالنجاسة فيلمس بثيابه تلك دون شعور ثياب أخيه الكبير أو ثيابي ولكن آثار البلل لا تظهر على ثياب الكبير نتيجة الملامسة، فهل يلزم الكبير غسيل ثيابه لتطهيرها أما أنها لا تعتبر نجاسة لأنها لم تظهر عليه آثار البلل؟ وهل هناك طريقة للتطهير من النجاسة غير الغسيل كالتعريض للشمس مثلًا؟ وهل هناك سن يكون فيها بول الولد غير نجس أم أنه نجس منذ الولادة، أفيدونا أفادكم الله؟","title":"حكم بول الصبي","answer":"الجواب: بول الطفل نجس مطلقًا من حين الولادة إلى آخر حياته هو نجس لكنه في حالة الطفولة وعدم أكل الطعام تكون نجاسته مخففة يكفي فيها الرش والنضح حتى يأكل الطعام ويتغذى بالطعام، فإذا تغذى بالطعام صار يغسل لقول النبي ﷺ: بول الغلام ينضح وبول الجارية يغسل.\nفالمقصود أنه مادام لا يتغذى بالطعام بوله نجاسة خفيفة يجب فيها الرش والنضح، وإذا كان ثوب الصبي مبلل بالنجاسة ثم باشر ثوبًا آخر طاهر فإن هذا البلل ينجس الثوب الذي يلامسه؛ لأنه رطب إذا كان رطبًا، أما إذا كانت رطوبته خفيفة ما يؤثر في الثوب الذي يلامسه فلا بأس لا يتنجس لكن إذا كانت رطوبته واضحة وبينة فإنه لابد تؤثر في الثوب الذي تلامسه ولو ما بان ذلك بينونة ظاهرة فينبغي غسل ما أصاب الثوب الجديد الطاهر من هذا البلل يتحراه ويغسله بالماء وليس هناك طريق غير الماء، الشمس ما تكفي، لابد من غسله بالماء ولهذا كان النبي إذا أصابه بول الصبي صب عليه الماء عليه الصلاة والسلام، وإذا كان صغيرًا أتبعه بالماء ولم يعصره ولم يغسله بل يكفي رشه بالماء كما تقدم.","link":"https://binbaz.org.sa/fatwas/7885/حكم-بول-الصبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19510.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":9895,"question":"ما حكم الصلاة في ثوب فيه نجاسة يقول: مع علمي بذلك، هل تصح صلاتي في مثل هذه الحالة؟","title":"حكم الصلاة في ثوب فيه نجاسة","answer":"الجواب: لا يجوز أن يصلي في ثوب فيه نجاسة، لابد يزيل النجاسة بالغسل، أو يبد له أما لو صلى ناسيًا أو جاهلًا ، ولم يعلم إلا بعد الصلاة فالصلاة صحيحة.","link":"https://binbaz.org.sa/fatwas/8063/حكم-الصلاة-في-ثوب-فيه-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27307.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":10115,"question":"الطالب عبدالله محمود طاهر بعث يسأل ويقول: إذا اكتشفت في أن أحد ملابسي شيئًا من النجاسة فهل أعيد ما صليت في تلك الملابس؟","title":"حكم من اكتشف بعد الصلاة أن في ثيابه نجاسة","answer":"الجواب: لا، لا تلزمك الإعادة، إذا وجد الإنسان في ثيابه أو في سراويله أو نحو ذلك نجاسة بعد الصلاة فإنه لا يعيدها، وهكذا لو كان يعلم ثم نسي حتى فرغ من الصلاة لا يعيد على الصحيح؛ لأن الرسول ﷺ في بعض صلواته نبهه جبرائيل قال: إن في نعليك قذرًا، فخلعهما عليه الصلاة والسلام ولم يعد أول الصلاة، فدل ذلك على أنه لا تعاد إذا صلاها وهو جاهل أو ناسي ولم يعلم إلا بعد الفراغ فإنه لا يعيد، هذا هو الصواب. إذا سلم ثم علم أن في إزاره أو قميصه أو سراويله أو بشته نجاسة ولم يعلم إلا بعد الفراغ فإن صلاته صحيحة، هذا هو الصواب، بخلاف الحدث، أما الحدث يعيد، لو صلى يظن أنه على طهارة ثم لما فرغ علم أنه ليس على طهارة وأنه قد أحدث ريح أو بول أو غير ذلك فإنه يعيد الصلاة عند أهل العلم؛ لقوله ﷺ: لا تقبل صلاة بغير طهور فلا تقبل الصلاة إلا بطهارة، أما النجاسة التي في الثوب فلها حكم آخر، النجاسة في الثوب أو في البشت أو في النعل أو نحو ذلك إذا لم يعلم إلا بعد الصلاة صلاته صحيحة، هذا هو المعتمد هذا هو الصواب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8286/حكم-من-اكتشف-بعد-الصلاة-ان-في-ثيابه-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33404.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":10166,"question":"تقول أختنا: أحياناً أقوم بحمل طفلتي أثناء الصلاة لبكائها الشديد ويكون عليها الحفاظ وقد أحدثت به، فما حكم صلاتي وحملي لها أثناء الصلاة والحال ما ذكرت، جزاكم الله خيرًا؟","title":"حكم حمل الطفل في الصلاة وعليه الحفاظة بها نجاسة","answer":"الجواب: إذا كان فيها أذى لا تحمليها، إذا كان فيها الأذى ... فيها الأذى لا تحمليها، أما إذا كانت نظيفة فلا بأس، فقد ثبت عنه ﷺ أنه صلى وهو حامل أمامة بنت زينب بنت بنته، يصلي بها والناس ينظرون فإذا سجد وضعها وإذا قام حملها عليه الصلاة والسلام، وقد حمل العلماء ذلك على أنها كانت نظيفة طاهرة.\nفالأحوط لك أن لا تفعلي هذا إلا إذا كنت تعرفين أنها طاهرة، هذا هو الأحوط ولا تحمليها وهي فيها النجاسة، نعم.\nالمقدم: جزاكم الله خيرًا، ما حكم الصلاة التي صلتها وحالها ما ذكرت؟\nالشيخ: نرجو أن لا إعادة عليها إن شاء الله، نرجو أن لا إعادة عليها، لكن في المستقبل تحتاط.\nالمقدم: بارك الله فيكم، أحسن إليكم، وجزاكم خير الجزاء.","link":"https://binbaz.org.sa/fatwas/8337/حكم-حمل-الطفل-في-الصلاة-وعليه-الحفاظة-بها-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27717.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":10336,"question":"تسأل عن الغبار المنبعث من مكان نجس هل يعتبر الغبار أيضاً من النجاسة؟","title":"حكم الغبار المنبعث من مكان نجس","answer":"الجواب: لا يضر. الغبار لا يضر، الغبار والدخان لا يضر، هذا مما يعفى عنه، فلا ينبغي الوسوسة في هذا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8502/حكم-الغبار-المنبعث-من-مكان-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31502.mp3","categories":["النجاسات وإزالتها"," الوسواس بأنواعه"]},{"id":10339,"question":"تسأل عن الغبار المنبعث من مكان نجس هل يعتبر الغبار أيضاً من النجاسة؟","title":"حكم الغبار المنبعث من مكان نجس","answer":"الجواب: لا يضر. الغبار لا يضر، الغبار والدخان لا يضر، هذا مما يعفى عنه، فلا ينبغي الوسوسة في هذا. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8502/حكم-الغبار-المنبعث-من-مكان-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_315/31502.mp3","categories":["النجاسات وإزالتها"," الوسواس بأنواعه"]},{"id":10831,"question":"ننتقل إلى سؤاله الثاني يقول فيه: صليت وملابسي الداخلية على غير طهارة، وكنت ناسيًا، هل أعيد ما صليت؟","title":"حكم الصلاة في الثوب النجس","answer":"الجواب:  إذا صلى المسلم وفي ثيابه نجاسة، ولم يذكر إلا بعد الصلاة، أو لم يعلم إلا بعد الصلاة فإن صلاته صحيحة على الصحيح، ومعذور بالجهل والنسيان، إذا انتهت صلاته قبل أن يعلم، لقول الله سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] ولما ثبت عنه ﷺ أنه دخل الصلاة يومًا، وفي نعليه قذر، فأخبره جبرائيل في أثناء الصلاة أن بهما قذرًا فخلعهما، ولم يعد أول الصلاة، بل استمر في صلاته، لأنه جاهل بذلك القذر، فهكذا من دخل في صلاته وفي ملابسه شيء من النجاسة، ولم يعلم، أو لم يذكر إلا بعد الفراغ فإن صلاته صحيحة في أصح قولي العلماء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9017/حكم-الصلاة-في-الثوب-النجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35510.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":10837,"question":"ننتقل إلى سؤاله الثاني يقول فيه: صليت وملابسي الداخلية على غير طهارة، وكنت ناسيًا، هل أعيد ما صليت؟","title":"حكم الصلاة في الثوب النجس","answer":"الجواب:  إذا صلى المسلم وفي ثيابه نجاسة، ولم يذكر إلا بعد الصلاة، أو لم يعلم إلا بعد الصلاة فإن صلاته صحيحة على الصحيح، ومعذور بالجهل والنسيان، إذا انتهت صلاته قبل أن يعلم، لقول الله سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] ولما ثبت عنه ﷺ أنه دخل الصلاة يومًا، وفي نعليه قذر، فأخبره جبرائيل في أثناء الصلاة أن بهما قذرًا فخلعهما، ولم يعد أول الصلاة، بل استمر في صلاته، لأنه جاهل بذلك القذر، فهكذا من دخل في صلاته وفي ملابسه شيء من النجاسة، ولم يعلم، أو لم يذكر إلا بعد الفراغ فإن صلاته صحيحة في أصح قولي العلماء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9017/حكم-الصلاة-في-الثوب-النجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35510.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":11411,"question":"تقول أختنا: رجل في سفر أدركته الصلاة، وكان لديه ثوبان، أحدهما أصابته نجاسة، ولكنه لا يعلم أي الثوبين، فصلى في واحد، ثم صلى في الآخر، هل صلاته حينئذ صحيحة؟ وماذا عليه أن يفعل؟ جزاكم الله خيرًا.","title":"حكم من له ثوبان، وفي أحدهما نجاسة ولم يميز بينهما","answer":"الجواب:  صلاته صحيحة، وقد احتاط، ما دام النجاسة في أحدهما وصلى الصلاة مرتين، مرة في هذا، ومرة في هذا؛ قد احتاط، وإن تحرى وصلى في أحدهما يظنه الطاهر؛ كفى، والحمد لله. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9590/حكم-من-له-ثوبان-وفي-احدهما-نجاسة-ولم-يميز-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38010.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":11536,"question":"يقول: كلب المزرعة -أجلكم الله- عندما أقدم له الطعام قد يلمسني، وقد يلمس ملابسي، فهل يجب علي حين ملامسته لملابسي أن أغيرها؟ وهل يجب علي أن أعيد الوضوء؟ جزاكم الله خيرًا.","title":"حكم من لمسه الكلب أو لمس ملابسه","answer":"الجواب: الوضوء ليس عليك إعادة الوضوء، لكن إذا مس رطوبة منه شيئًا من ثوبك تغسل محل الرطوبة، أما إذا مس ثوبك جلده وهو يابس ما يضر، لكن إذا كان رطوبة: شيء من بوله، أو ريقه (لعابه) تغسل ما أصابك سبع مرات، ما أصاب رجلك، أو ثوبك تغسله سبع مرات، ويكون فيها واحده تراب، مع شيء من التراب في الأولى أفضل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9718/حكم-من-لمسه-الكلب-او-لمس-ملابسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38514.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":12021,"question":"إذا بال طفل صغير على ملابس أبيه، فهل يلزم الأب أن يغسل الثوب كله أو يغسل الجزء المبتل فقط؟ جزاكم الله خيرًا.","title":"كيفية تطهير النجاسة الواقعة على الثوب والأرض","answer":"الجواب:  إذا كان الطفل يأكل الطعام، يتغذى بالطعام، يغسل ما أصاب الثوب منه غسلًا، ولا يغسل الثوب كله، ولكن يغسل ما أصابه البول، وهكذا بقية النجاسات يغسل محل النجاسة فقط من البدن، ومن الثوب، ومن البقعة في الأرض، وما سوى ذلك طاهر. وأما إن كان الصبي لا يأكل الطعام، لا يتغذى بالطعام، إنما يتغذى بالحليب، باللبن، بالرضاع من أمه، فإنه لا يجب الغسل، بل يرش مكان البول رشًا، يمر عليه الماء فقط، ويكفي، يمر عليه الماء من دون حاجة إلى فرك، ولا غسل، بل إذا مر عليه الماء؛ كفى؛ لأن النبي ﷺ بال على ثوبه، طفل لا يأكل الطعام، فأتبعه الماء، ولم يغسله -عليه الصلاة والسلام-روقال -عليه الصلاة والسلام-: بول الرضيع الذي لا يأكل الطعام ينضح، وبول الجارية يغسل فبول الغلام الذي لا يأكل، لا يتغذى بالطعام إنما يرش رشًا، وينضح محله، يتبع بالماء، ويكفي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10206/كيفية-تطهير-النجاسة-الواقعة-على-الثوب-والارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43212.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":12249,"question":"يقول أيضًا: هل تجوز الصلاة مع أخينا الجزار وثيابه ملوثة بالدم وهو إمام؟","title":"حكم الصلاة خلف إمام ثيابه ملوثة بالدم","answer":"الجواب:  ليس له أن يصلي في الثياب الملوثة بالدم، ولا يكون إمامًا، الجزار عليه أن يتخذ للصلاة ثيابًا طاهرة، أو يغسل ما أصابه من الدم قبل أن يصلي، سواءٌ كان إمامًا، أو منفردًا أو مأمومًا، ليس له أن يصلي بالناس، ولا أن يصلي وحده وفيه النجاسة، وليس لك أن تصلي خلفه، بل يجب أن تنكر عليه، وأن تعلمه حتى يطهر ثيابه، أو يتخذ للصلاة ثيابًا نظيفة. أما ما دامت ثيابه نجسة؛ فإنها لا تصح صلاته، بل يجب أن يطهرها، أو يتخذ ثيابًا نظيفة للصلاة، هذا هو الواجب عليه وعلى كل من أصابته النجاسة إلا إذا وقع في وقت ليس عنده قدرة على غسلها في مكان في البر مثلًا، ما عنده ماء، ويخشى .... الصلاة فإنه يصلي على حسب حاله، ولو في الثوب النجس، وصلاته صحيحة حتى يجد ماءً يغسل هذا الثوب، أو يجد ثوبًا بدله حتى يزيله ما دام مضطرًا، ليس عنده إلا هذا الثوب الواحد وهو في البرية، أو سجين ما تيسر له أن يعطيه أحدًا ثوبًا طاهرًا، ولم يستطع غسله، فالله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] يصلي حتى يجعل الله فرجًا ومخرجًا، فإذا قدر على إبداله، أو تغسيله؛ وجب عليه ذلك.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10443/حكم-الصلاة-خلف-امام-ثيابه-ملوثة-بالدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44813.mp3","categories":["النجاسات وإزالتها","صلاة الجماعة"]},{"id":12537,"question":"له سؤال آخر يقول: هل وقوع النجاسة على جسم الإنسان تلزمه بإعادة الوضوء، أم أنه يكفي إزالة النجاسة، والصلاة دون إعادة الوضوء؟","title":"أثر وقع النجاسة على وضوء الإنسان","answer":"الجواب:  إذا وقعت على جسم الإنسان نجاسة بعد الوضوء، بأن وقع عليه شيء من بول صبي، أو غير ذلك من أنواع النجاسة؛ فإنه يغسل محل النجاسة، ويكفي، ولا يعيد الوضوء، بل يغسل ما أصاب النجاسة من ثوب، أو بدن، وليس عليه أن يعيد الوضوء. أما إذا كانت النجاسة من نفسه بأن خرج منه البول؛ فهذا يستنجي، ويعيد الوضوء، أما لو أصابه نجاسة من طفل عنده، طفل، أو من غيره، أو سقط عليه دم؛ يغسل ما أصابه، ويكفي، والوضوء صحيح. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10744/اثر-وقع-النجاسة-على-وضوء-الانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_409/40906%20%20.mp3","categories":["النجاسات وإزالتها","نواقض الوضوء"]},{"id":12697,"question":"هل القي يؤثر على طهارة الملابس، أم لا؟","title":"حكم القيء","answer":"الجواب:  يعفى عن قليله، وأما الأكثر فينبغي فيه الغسل؛ لأن كثيرًا من أهل العلم ألحقوه بالبول، فينبغي أن ينظف منه الملابس، وما أصاب البدن، أما الشيء القليل؛ فيعفى عنه، كما يعفى عن يسير الدم، ويسير الصديد، ونحو ذلك. نعم. المقدم: جزاكم الله خيرًا، سواءً كان من الكبار، أو من الصغار؟ الشيخ: نعم نعم. المقدم: الحال واحد. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10907/حكم-القيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45902.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13000,"question":"السائلة (ع. ن) من الرياض تقول: قضيتي الأولى ما يلي: تذكر بأنها شابة ومتزوجة، وعندها طفلين -تحمد الله على ذلك- تقول: المشكلة -يا سماحة الشيخ- هو أنني عندما كنت في الأيام الأولى من زواجي لم أكن أغتسل من الجنابة بسبب الجهل في ذلك؛ لأنني كنت أظن بأن الاغتسال خاص بالرجال فقط، دون النساء، وعندما علمت بأن المرأة يجب عليها الاغتسال؛ ندمت ندمًا كثيرًا على ما كان من جهلي، وأنا الآن لا أدري ما عدد الصلوات التي كنت أصليها، وأنا علي الجنابة، وقد جلست على تلك الفترة ما يقارب من شهرين تقريبًا، ماذا علي يا -سماحة الشيخ- تجاه تلك الصلوات؟","title":"حكم من كان يصلي على جنابة جهلاً منه","answer":"الجواب:  ليس عليك إلا التوبة، التوبة تجب ما قبلها، يقول النبي ﷺ: الإسلام يجب ما قبله، والتوبة تجب ما كان قبلها والحمد لله، وإن قضيت الصلوات بالظن؛ فهو طيب، وحسن؛ خروجًا من الخلاف، إن قضيت ما تظنين أنك صليتها، وعليك الجنابة؛ فهذا حسن؛ من باب الخروج من الخلاف، وإلا فأنت تنفعك التوبة، ويكفيك التوبة، والحمد لله؛ لأجل جهلك، وعدم عنايتك بالسؤال، فأنت قد فرطت، وأسأت؛ فعليك التوبة إلى الله، وترك الصلاة كفر، والكافر توبته تكفي، إذا تاب الكافر؛ ما عليه قضاء، نسأل الله السلامة، نعم، والذي يصلي وعليه جنابة حكمه حكم الذي ما يصلي، نسأل الله العافية، نعم. المقدم: نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/11217/حكم-من-كان-يصلي-على-جنابة-جهلا-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50413.mp3","categories":["الطهارة لصحة الصلاة","النجاسات وإزالتها"]},{"id":13225,"question":"بعد ذلك ننتقل إلى رسالة السائل علي عبدالله من جمهورية مصر العربية، ومقيم بالمملكة يقول: أنا -والحمد لله- محافظ على الصلوات في الجماعة في أوقاتها، وفي مساجد الله، ولكن في بعض الأوقات ينزف أنفي دمًا أثناء الوضوء، ويستمر معي هذا النزيف لفترة طويلة، وربما يستمر لفترة أطول، وأسد ذلك بشيء من القماش، أو اللفاف وقت الصلاة، هل في ذلك خطأ، وبماذا تنصحونني يا سماحة الشيخ؟","title":"ما يفعل من خرج الدم من أنفه وخشي خروج وقت الصلاة؟","answer":"الجواب:  لا حرج هذا فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] هذا هو الواجب، وضع شيء يمسكه، وسد الأنف، هذا من العلاج، ولا حرج في ذلك، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/11504/ما-يفعل-من-خرج-الدم-من-انفه-وخشي-خروج-وقت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51219.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13227,"question":"يقول: في بعض الأوقات قد يكون أو يقع بعض الدم على الملابس وأنا في الصلاة، هل أعيد الصلاة، وهل أغير ملابسي؟","title":"حكم من وقع على ثوبه دم أثناء الصلاة","answer":"الجواب: إذا كان قطرات يسيرة؛ يعفى عنها، وأما إذا كانت كثيرة؛ يقطع الصلاة حتى يبدل الثوب، ويغسلها، أما إذا كانت قطرات يسيرة؛ يعفى عنها؛ لأن الله -جل وعلا- يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] .. لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ويقول: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]  فالشيء اليسير يعفى عنه قطرات من دم أو قيح أو صديد، هذا يعفى عنها؛ لأن الله -جل وعلا- رفع الحرج عن هذه الأمة، نعم.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11506/حكم-من-وقع-على-ثوبه-دم-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51220.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13340,"question":"إحدى الأخوات المستمعات تقول: السائلة التي لقبت نفسها بالصابرة صبر أيوب من الضفة الغربية قضاء الخليل، تقول: منذ أن كان عمري اثني عشر عامًا، وأنا أصوم وأصلي الفروض الواجبة علي، وبعد خمس وعشرين سنة وقعت في المرض، والآن أشعركم أنني أتألم كثيرًا من الماء، وأقوم بالتيمم، وحينما يأتي إلي المرض؛ أنقطع عن الصلاة، وجهوني تجاه هذه القضية، جزاكم الله خيرًا.","title":"حكم التيمم للمريض وترك الصلاة من أجل المرض","answer":"الجواب: شفاك الله وعافاك، نسأل الله لك الشفاء والعافية من كل سوء، وأن يصلح قلبك ودينك، وأن يعيذنا وإياك من كل سوء، وسائر المسلمين، وإذا كنت يضرك الماء؛ فلا مانع من التيمم، والله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والذي يضره الماء حكمه حكم من لم يجد الماء، يتيمم والحمد لله، يضرب التراب بيديه، ويمسح وجهه وكفيه بذلك، ويكتفي بهذا عن الماء. أما الصلاة فعليك أن تصلي على حسب طاقتك، إن استطعت قائمة؛ صليت قائمة، وإن استطعت قاعدة؛ صليت قاعدة، بدلًا من القيام، إذا عجزت عن القيام، فإن لم تستطيعي القيام، ولا القعود؛ فعليك أن تصلي على الجنب، والأفضل على الجنب الأيمن إذا تيسر ذلك، فإن عجزت؛ فصلي مستلقية، ورجلاك إلى القبلة. ولا يجوز ترك الصلاة أبدًا، بل عليك أن تصلي على إحدى هذه الصفات حسب الطاقة، ما دام العقل موجودًا. إن قدرت قائمة؛ صليت قائمة، وإن عجزت عن القيام؛ صليت قاعدة، وإن عجزت عن القعود؛ صليت على جنب، وإن عجزت؛ صليت مستلقية، هكذا أجاب النبي ﷺ لما سأله بعض المرضى، قال له ﷺ: صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع؛ فمستلقيًا هكذا رواه البخاري في الصحيح بدون ذكر الاستلقاء، وزاد النسائي بإسناد جيد ذكر الاستلقاء على الظهر. فالحاصل: أن هذا هو الواجب على كل مريض أن يصلي على حسب طاقته، ما دام العقل موجودًا، أما إذا زال العقل؛ سقط التكليف كالمجانين، وأشباههم.  نسأل الله لك الشفاء والعافية، وأن يمن عليك بالصحة التي تعينك على طاعة الله كما شرع  نعم.","link":"https://binbaz.org.sa/fatwas/11626/حكم-التيمم-للمريض-وترك-الصلاة-من-اجل-المرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_476/47615.mp3","categories":["قضايا المرأة","النجاسات وإزالتها","التيمم"]},{"id":13596,"question":"تقول السائلة سماحة الشيخ: إذا توضأ الإنسان، وكانت قدماه مبتلة بالماء، ومشى على فراش به نجاسة جافة، فهل يلزمه أن يغسل قدميه؟ وهل تصح الصلاة في مكان به نجاسة جافة؟","title":"حكم من توضأ ومشى على نجاسة جافة","answer":"الجواب: إذا مشى على النجاسة الجافة، ورجله رطبة؛ وجب عليه أن يغسلها إذا تجاوز المحل هذا، وهكذا لو مشى على محل رطب فيه نجاسة، ورجله يابسة، ولكن محلًا رطبًا، وفيه نجاسة، وطئ عليها؛ يغسل رجله أيضًا. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11932/حكم-من-توضا-ومشى-على-نجاسة-جافة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52719.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13758,"question":"السائلة في آخر أسئلتها تقول، السائلة من دمشق أم نعيم: أصاب فراشي نجاسة، ثم جفت، وكنت مريضة، فاضطررت للصلاة قاعدة عليه، ولكني مددت فوقها ملاءة، أو فراشًا طاهرًا، هل صلاتي صحيحة؟ وإذا لم تكن كذلك، فهل علي الإعادة لصلواتي الفائتة، وهي كثيرة؟","title":"حكم الصلاة على فراش نجس بعد تغطيته بشيء طاهر","answer":"الجواب: ليس عليك الإعادة، مادام وضعت عليه ملاءة طاهرة على محل النجاسة، وصليت؛ الحمد لله، ليس عليك إعادة. نعم.","link":"https://binbaz.org.sa/fatwas/12128/حكم-الصلاة-على-فراش-نجس-بعد-تغطيته-بشيء-طاهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53521.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13763,"question":"السائلة في آخر أسئلتها تقول، السائلة من دمشق أم نعيم: أصاب فراشي نجاسة، ثم جفت، وكنت مريضة، فاضطررت للصلاة قاعدة عليه، ولكني مددت فوقها ملاءة، أو فراشًا طاهرًا، هل صلاتي صحيحة؟ وإذا لم تكن كذلك، فهل علي الإعادة لصلواتي الفائتة، وهي كثيرة؟","title":"حكم الصلاة على فراش نجس بعد تغطيته بشيء طاهر","answer":"الجواب: ليس عليك الإعادة، مادام وضعت عليه ملاءة طاهرة على محل النجاسة، وصليت؛ الحمد لله، ليس عليك إعادة. نعم.","link":"https://binbaz.org.sa/fatwas/12128/حكم-الصلاة-على-فراش-نجس-بعد-تغطيته-بشيء-طاهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53521.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13841,"question":"تسأل أختنا وتقول: أسألكم عن سؤر البهائم هل لنا أن نتوضأ منه أو لا؟","title":"هل يجوز الوضوء من سؤر البهائم؟","answer":"الجواب: البهائم مختلفة تتنوع منها سؤر الإبل والغنم والبقر وغيرها مما يؤكل لحمه، هذا لا بأس به.\nالمقدم: سؤر الطاهر منها؟\nالجواب: سؤر الطاهر ....... الإبل والبقر والغنم والظباء والجواميس وأشباه ذلك لا بأس بها؛ لأنها طاهرة. أما سؤر الكلب فلا، يجب إراقته ولا يتوضأ منه؛ لأنه نجس، وقد أمرنا بغسل الإناء منه سبع مرات إحداهن بالتراب وهي الأولى. وأما سؤر الحمار والبغل الصواب أنه لا حرج فيه؛ لأنه تعم به البلوى، وإن كان محرمًا لكن تعمه البلوى، وهكذا الهرة، القط سؤره لا بأس به. وأما سؤر الحيوانات الأخرى كالأسود والنمور والذئاب فيما تمر عليه من الحيضان ومجامع الناس الماء في البر فلا يضر ذلك والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12212/هل-يجوز-الوضوء-من-سور-البهاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60211.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14162,"question":"من المدينة المنورة السائلة: (م. ط. ع) تقول في هذا  هل يجوز أن نضع الثياب التي يوجد بها نجاسة مع الثياب الأخرى التي لا يوجد بها نجاسة وذلك في الغسالة معًا؟","title":"حكم غسل الثياب النجسة مع الثياب الطاهرة","answer":"الجواب: إذا كان الغسل يحصل به المطلوب فلا بأس، إذا كان الغسل يحصل به المطلوب تنظيف الجميع فلا بأس؛ لأنه يطهر هذه وهذه، يطهر النجاسة وينظف السليمة، والغسل يزيل ما فيها من النجاسة مع وجود التنظيف فلا يضر ذلك إذا كان غسلًا تحصل به إزالة النجاسة، يعني: يعصر الثوب ثم يغسل ثم يعصر حتى يغلب على الظن أن النجاسة زالت فلا بأس، وإذا غسلت هذه وحدها وهذه وحدها هذا أحسن وأسلم، تغسل النجسة وحدها والطاهرة وحدها أسلم.\nولكن إذا غسلت جميعًا وعمل ما يلزم من جهة غلبة الظن أن أثر النجاسة زال كفى والحمد لله.","link":"https://binbaz.org.sa/fatwas/12602/حكم-غسل-الثياب-النجسة-مع-الثياب-الطاهرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54623.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14180,"question":"السائل يقول في آخر أسئلته: هل تجوز الصلاة في المسجد منفردًا بلباس العمل كالجزار مثلًا على ثوبه دم والمهن الأخرى، حدثونا في ضوء هذا السؤال يا سماحة الشيخ ونرجو كلمة؟","title":"حكم الصلاة في الملابس التي فيها دم","answer":"الجواب: الواجب على المؤمن أن لا يصلي إلا في ملابس طاهرة، الجزار لا يصلي في ملابس فيها دم؛ لأن الدم نجس، وهكذا غيره كل صاحب مهنة يجب أن تكون ثيابه طاهرة سليمة عند الصلاة لا يصير فيها نجاسة؛ لأن من شرط الصلاة أن تكون ثياب المصلي طاهرة وبقعته طاهرة، فليس للجزار ولا غيره أن يصلي في الملابس التي فيها الدماء أو فيها البول أو غيره من النجاسات، بل يجب أن يصلي في ثياب طاهرة وبدن طاهر. نعم.\nوهكذا البقعة تكون طاهرة. نعم.\nالمقدم: هل من كلمة يا سماحة الشيخ لأولئك الذين الحقيقة يصلون.. العمال وغيرهم يا شيخ؟\nالشيخ: نعم، نوصي الجميع بتقوى الله وأن يصلوا كما شرع الله، وأن يحذروا التساهل في ذلك لا من جهة السترة ولا من جهة البقعة تكون البقعة نظيفة وتكون الملابس نظيفة سليمة من النجاسات والواجب عليهم أن يصلوا في الجماعة، يجب على أهل العمل أن يصلوا في الجماعة في المساجد ثم يعودوا إلى أعمالهم، نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12623/حكم-الصلاة-في-الملابس-التي-فيها-دم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54715.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14216,"question":"السائل علي خالد يقول: صليت المغرب والعشاء ولم تكن ثيابي طاهرة، هل علي الإعادة في مثل هذه الحالة؟","title":"هل تجب الإعادة على من صلى في ثياب نجسة؟","answer":"الجواب: إذا كنت تعلم أنها نجسة فعليك الإعادة، أما إذا كنت لا تعلم إلا بعد الصلاة لجهل أو نسيان فالصلاة صحيحة، أما إن كنت حين صليت فيها تعلم أنها نجسة فإن الصلاة غير صحيحة، أما لو كنت لا تعلم إلا بعد الصلاة؛ أُخبرت بعد الصلاة أو ذُكِّرت بعد الصلاة فالصلاة صحيحة. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12667/هل-تجب-الاعادة-على-من-صلى-في-ثياب-نجسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54817.mp3","categories":["الطهارة لصحة الصلاة","النجاسات وإزالتها"]},{"id":14701,"question":"يقول السائل: نحن نعلم أن المسلم يجب أن يصلي في ملابس طاهرة، ولكننا لا نعلم هل يجوز للمسلم أن يتوضأ في ملابس غير طاهرة، ولكنها في الحقيقة غير نجسة نجاسة عينية كملابس النوم مثلًا؟","title":"حكم الصلاة بملابس النوم","answer":"الجواب: ليس له أن يصلي في ملابس نجسة، أما الملابس التي يشك فيها فلا بأس، ملابس النوم ما هي بنجسة، إلا إذا علم أنه أصابها نجاسة يغسل النجاسة.  وأما كونه ينام فيها النوم لا ينجسها إلا إذا أصابها بول أو مذي أو شيء من النجاسات الأخرى يغسل، يغسل ما أصابها، فإذا علم أن فيها نجاسة لا يصلي فيها، أما إذا كان لم يعلم، فالأصل الطهارة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13193/حكم-الصلاة-بملابس-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56020.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14707,"question":"يقول السائل: نحن نعلم أن المسلم يجب أن يصلي في ملابس طاهرة، ولكننا لا نعلم هل يجوز للمسلم أن يتوضأ في ملابس غير طاهرة، ولكنها في الحقيقة غير نجسة نجاسة عينية كملابس النوم مثلًا؟","title":"حكم الصلاة بملابس النوم","answer":"الجواب: ليس له أن يصلي في ملابس نجسة، أما الملابس التي يشك فيها فلا بأس، ملابس النوم ما هي بنجسة، إلا إذا علم أنه أصابها نجاسة يغسل النجاسة.  وأما كونه ينام فيها النوم لا ينجسها إلا إذا أصابها بول أو مذي أو شيء من النجاسات الأخرى يغسل، يغسل ما أصابها، فإذا علم أن فيها نجاسة لا يصلي فيها، أما إذا كان لم يعلم، فالأصل الطهارة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13193/حكم-الصلاة-بملابس-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56020.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14741,"question":"أولى رسائل هذه الحلقة رسالة وصلة إلى البرنامج من المستمع بشير حمد، وسعد صالح، يسألان فيها عن جلد الميتة إذا دبغ، يقولان: إنا وجدنا في بعض كتب الفقه: أن جلد الميتة لا يجوز استعماله وإن دبغ، ويرجون الإجابة الصحيحة. جزاكم الله خيرًا.","title":"حكم استعمال جلد الميتة بعد دبغه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد ثبت في الأحاديث الصحيحة عن رسول الله -عليه الصلاة والسلام- ما يدل على أن جلد الميتة يطهر بالدباغ، متى دبغ طهر، ثبت في صحيح مسلم -رحمه الله- عن ابن عباس -رضي الله تعالى عنهما- عن النبي ﷺ أنه قال: إذا دبغ الإهاب فقد طهر قال أهل اللغة: الإهاب جلد الميتة، جلد مأكول اللحم، فإذا أخذ الإنسان الجلد من الميتة البقرة أو شاة أو بعير ودبغه طهر، يستعمل في اليابسات والمائعات جميعًا، هذا هو الصواب؛ لأنها وصفت بالطهارة، وفي لفظ آخر يقول ﷺ: أيما إهاب دبغ فقد طهر وفي الصحيح أيضًا: أن ميمونة كان عندها شاة فماتت، فقال النبي ﷺ: هلا أخذتم إهابها فدبغتموه، وانتفعتم به. فالحاصل: أنه يجوز الانتفاع بجلود الميتة مما يؤكل لحمه، بعد الدباغ في كل شيء، من رطب ويابس، في اللبن وفي الماء وفي غير ذلك، هذا هو الصواب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13236/حكم-استعمال-جلد-الميتة-بعد-دبغه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49009.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14955,"question":"المقدمة حنان العبدالواحد، بعثت بهذه الرسالة تقول فيها: لقد وقع على ثوبي نقط ندم من كبد الإبل، وأنا أقطعها، ولا أعلم بذلك إلا من بعد شفتها، وأنني قد صليت في ثوبي صلاة الظهر والعصر والمغرب، فهل أقضيها أم لا؟جزاكم الله عني خير الجزاء.","title":"هل تعيد الصلاة من أصاب ثيابها دم الإبل دون علمها؟","answer":"الجواب: لا قضاء، ما أصاب الثوب من نقط الدم، ولم تعلميها إلا بعد الصلاة، فلا إعادة على الصحيح، إذا نسي الإنسان النجاسة، أو جهلها في ثوبه، ولم يعلم إلا بعد الصلاة، فلا قضاء عليه على الصحيح من أقوال العلماء؛ لأن النبي ﷺ كان ذات يوم يصلي وفي نعليه أذىً فأخبره جبرائيل -عليه الصلاة والسلام- بأنه فيهما قذرًا؛ فخلعهما ولم يعد أول الصلاة -عليه الصلاة والسلام-، فدل ذلك على أن الصلاة لا تعاد إذا كان هناك نجاسة في نعل أو في ثوب فلم يعلم بها إلا بعد الصلاة، نعم. لكن الحدث لا، إذا كان مثلاً صلى يظنه على طهارة، ثم بان أنه على غير طهارة، فهذا يعيد على كل حال عند جميع أهل العلم، صلى الإنسان أو صلت المرأة تحسب أنها على طهارة، ثم ذكر أو ذكرت أنها حين صلت ليست على طهارة، قد خرج منها بول أو ريح، أو ما أشبه هذا؛ تعيد الصلاة عند جميع أهل العلم، ليس مثل النجاسة، نعم.\nالمقدم: لكن هل يعتبر الدم الواقع من كبد الإبل نجس؟\nالجواب: الأقرب -والله أعلم- أنه ما يعد، ما دام في أثناء الكبد شيء متعلق باللحم ما يعد شيئًا، ما يعد إلا طاهر، هذا هو الأقرب، ما يكون في أثناء اللحم وبعد الذبح في أثناء اللحم في البطن في الكبد في الأمعاء في أشباه ذلك.  المقصود: أن الدم الذي يبقى في اللحوم وفي العروق ما يضر، إنما الذي ينجس ويضر المسفوح الذي عند الذبح، لكن على كل حال لو فرضنا أن بها نجاسة من نقط دم آخر يسمى نجسًا، أو من الدم المسفوح، أو من النجاسات الأخرى من بول أو غيره لم تعلم به إلا بعد الصلاة، فلا إعادة، نعم. المقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13452/هل-تعيد-الصلاة-من-اصاب-ثيابها-دم-الابل-دون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_648/nour_64805.mp3","categories":["الطهارة لصحة الصلاة","النجاسات وإزالتها"]},{"id":15054,"question":"السؤال الأخير في رسالته عن النجاسة، يقول: إذا صلى المسلم بثوب أو قميص نجس ناسيًا، فما حكم صلاته هذه من حيث الإعادة وعدمها؟","title":"حكم صلاة من صلى في ثوب نجس ناسيًا","answer":"الجواب: إذا صلى المسلم أو المسلمة في ثوب فيه نجاسة، سواء كان الثوب سراويل، أو قميص، أو إزار، أو كان فنيلة، أو غير ذلك، ولم يذكر إلا بعد الصلاة، فإن صلاته صحيحة على الصحيح.  وهكذا لو صلى في ثوب نجس، ثم لم يعلم بذلك إلا بعد الصلاة، فإن جهله عذر كالنسيان، فإذا صلى في ثوب نجس، أو ناسيًا، أو جاهلًا حتى فرغ من صلاته، فإن صلاته صحيحة؛ لأنه ﷺ صلى ذات يوم في نعل فيها قذر فنبهه جبرائيل على ذلك، فخلعهما، ولم يعد أول الصلاة، بل استمر في صلاته، فدل ذلك على أن أولها صحيح. فهكذا إذا لم يعلم إلا بعد فراغه منها، فصلاته صحيحة؛ لهذا الحديث، حديث \"أنه ﷺ صلى في نعليه وفيهما قذر، فنبهه جبرائيل على ذلك فخلعهما، ثم استمر في صلاته\" فدل ذلك على أن أولها صحيح بسبب الجهل، فهكذا الناسي، وهكذا من فرغ منها وكملها ناسيًا أو جاهلًا بالنجاسة التي في ثوبه أو في نعله، فإن صلاته صحيحة، لكن لو ذكر في أثناء الصلاة فخلع أجزأته الصلاة أيضًا، كما خلع النبي ﷺ نعليه، واستمر في صلاته، فلو كان في بشته نجاسة، أو في غترته نجاسة، أو في إزاره نجاسة، فخلعه وعليه ثوب يستر عورته، عليه قميص يستر عورته، فخلع إزاره الذي فيه النجاسة، أو سراويله في الحال أجزأته صلاته، نعم.\nالمقدم: لكن إذا كان عالمًا بالنجاسة قبل الصلاة، وكان هذا التفريط منه؟\nالشيخ: ثم نسي يعني؟\nالمقدم: نعم.\nالشيخ: ولو، إذا كان عالمًا، ثم نسي صحت صلاته، أما لو تعمد الصلاة بطلت صلاته، نعم.","link":"https://binbaz.org.sa/fatwas/13566/حكم-صلاة-من-صلى-في-ثوب-نجس-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_663/nour_66305.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":15071,"question":"هذه السائلة أختنا (ن. ز. ح. م) تقول: سماحة الشيخ، إذا صلى المرء فرضين، ثم اكتشف أن ملابسه بها نجاسة، وهو لا يعلم بها، هل يعيد الصلاة، أم ماذا يفعل؟","title":"حكم من تبين بعد الصلاة أن في ثيابه نجاسة","answer":"الجواب: الصواب أنه لا يعيد، ما دام لم يعلم إلا بعد الفراغ من الصلاة، سواءً كان ناسيًا أو جاهلًا، فصلاته صحيحة، ومن أدلة ذلك: أنه ﷺ صلى في نعليه، وفيها قذر، فأخبره جبرائيل أن بهما قذرًا، فخلعهما، ولم يعد أول الصلاة. ومن أدلة ذلك: قوله -جل وعلا-: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] قال الله: قد فعلت يقول النبي ﷺ: إن الله قال: قد فعلت. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13563/حكم-من-تبين-بعد-الصلاة-ان-في-ثيابه-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56403.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":15600,"question":"له سؤال آخر يقول فيه: يقول الله تعالى مخاطبًا نبيه موسى : إِنِّي أَنَا رَبُّكَ فَاخْلَعْ نَعْلَيْكَ إِنَّكَ بِالْوَادِ الْمُقَدَّسِ طُوًى[طه:12] هل الأمر بخلع النعلين هنا تعظيمًا لله، أم تعظيمًا للوادي المقدس؟ وإذا كان تعظيمًا لله فكيف يجوز أن يقف المسلم في الصلاة بين يدي ربه وهو لابس نعليه؟","title":"هل يجوز أن يصلي المسلم وهو لابس نعليه؟","answer":"الجواب: هذا شيء يتعلق بشريعة موسى حين أمره الله أن يخلع نعليه، ظاهره أن الوادي المقدس لا يطؤه بنعليه، فيحتمل أنها نعلان فيهما شيء من القذر، أو لأسباب أخرى، وقد أمر الله نبيه ﷺ أن يخلع نعليه في الصلاة -محمد- جاءه جبرائيل وقد صف في الصلاة وكبر، فأمره أن يخلع نعليه فخلعهما، فلما سلم قال للصحابة: إن جبرائيل أخبرني أن بهما قذرًا فخلعتهما، فإذا أتى الصلاة فلينظر في نعليه، فإن رأى فيهما قذرًا فليمسحه، ثم ليصلي فيهما وكان يصلي في نعليه -عليه الصلاة والسلام-. فشريعة موسى تخصه وليست شريعة لنا، قال تعالى: لِكُلٍّ جَعَلْنَا مِنْكُمْ شِرْعَةً وَمِنْهَاجًا[المائدة:48] أما شريعتنا فإنها تبيح لنا الصلاة في النعلين والخفين، كما صلى فيهما النبي ﷺ بل ذلك سنة؛ لقوله ﷺ: خالفوا اليهود، فإنهم لا يصلون في نعالهم. فالسنة لنا أن نخالف اليهود في ذلك، وأن نتبع محمدًا ﷺ في ذلك، فكان يصلي في نعليه، فلهذا يشرع لنا أن نصلي في نعلينا وخفينا إذا كانا نظيفين، فعلى المؤمن عند إتيانه المسجد أن يلاحظ نعليه وخفيه، وينظفهما إن كان فيهما شيء حتى لا يدخل بهما، وبهما قذر، كما فعل النبي ﷺ حين أخبره جبرائيل خلعهما، وإذا كانا نظيفين ليس بهما شيء فلا حرج أن يصلى فيهما في المسجد إذا كان حصباء أو تراب، أما إذا كان بفرش فلا بأس، لكن إذا خلعهما احتياطًا خلع النعلين مثلًا احتياطًا؛ لئلا يكون فيهما تراب كثير يوسخ المسجد، أو يكدر المصلين، فهذا حسن، وليس بلازم.  وأما الخفان فلا، إذا كان قد مسح عليهما لا يخلعهما يصلي فيهما؛ لأنهما إذا خلعهما بطل الوضوء، فإذا كان عليه خفان قد مسح عليهما للطهارة فلا يخلعهما، بل يصلي فيهما، لكن لا يدخل حتى ينظر فيهما، ويزيل ما بهما من أذى إن كان هناك أذى حتى لا يدخل فيهما إلا وهما نظيفان. أما النعل فأمرها أسهل في الإمكان خلعها؛ لأن النعل لا يمسح عليها، فإذا كان جاء على الطهارة، وعليه نعلان إن شاء خلعهما في المساجد المفروشة، وإن شاء تركهما، وإذا خلعهما من أجل مراعاة الناس؛ لئلا يستنكروا منه، أو لئلا يتكلموا عليه، أو لئلا يكون فيهما تراب يوسخ الفرش، فمن باب التحري للخير، ومن باب البعد عن التشويش فهذا حسن، وإلا فالأصل مع من قال بالصلاة فيهما، ولو كان المسجد مفروشًا إذا كانت نظيفة، إذا كانت النعلان نظيفتين فلا بأس بذلك؛ لفعل النبي ﷺ؛ ولقوله -عليه الصلاة والسلام-، ولكن مراعاة للناس اليوم في المساجد المفروشة إذا راعى الناس وخلعهما خوف أن يكون هناك تراب أو أوساخ ما فطن لها، أو أن الناس يعني: يستنكرون منه ذلك، وربما تكلموا عليه وجهلوه جهلًا منهم، فاتقى القالة، وحسم المادة، وجعلهما في مكان آخر، فهذا لا بأس به -إن شاء الله-، مراعاة لأمور الناس اليوم، واتقاء لما قد يقع من بعضهم من الجهل، والكلام الذي لا يناسب، والله  أعلم، نعم.","link":"https://binbaz.org.sa/fatwas/14145/هل-يجوز-ان-يصلي-المسلم-وهو-لابس-نعليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_694/nour_69406.mp3","categories":["النجاسات وإزالتها"]},{"id":15668,"question":"يسألان أيضًا عن الدم المسفوح ما هو؟","title":"معنى الدم المسفوح","answer":"الجواب: هو الدم الذي يخرج من البهيمة عند الذبح، الدم الذي يصب من البهيمة من حلقها عند الذبح، يقال له: مسفوح، وهو نجس ومحرم، وهكذا الدماء الذي تصب منها عند إصابتها بحادث، إذا أصابها حادث فسال الدم منها، فهذا مسفوح وهو المراق، المسفوح المراق، بخلاف....، يبقى في العروق، أو في اللحوم هذا يعفى عنه.","link":"https://binbaz.org.sa/fatwas/14212/معنى-الدم-المسفوح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70517.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":15785,"question":"من عمان، الأردن، مستمعة تقول: أختكم أم أنس، أم أنس تسأل فتقول: إن طفلي يرضع الحليب الاصطناعي، وهو يسترجع باستمرار عدة مرات في الساعة الواحدة، وقد يصيب ملابسي بعض الأحيان، وأنا أصلي بها دون غسل، فهل يلزمني أن أجدد وضوئي، أو أغير ملابسي؟ وهل صلاتي جائزة دون ذلك؟جزاكم الله خيرًا.","title":"حكم قيء الطفل","answer":"الجواب: كأنها تعني القيء.\nالمقدم: نعم. الشيخ: أنه يقيء من هذا الحليب الذي يشربه، المشروع لك أن تغسلي ما أصابك، يعني: بعض أهل العلم يرى هذا القيء كبوله، فالمشروع لك أن تغسلي هذه الملابس التي يصيبها إذا كان الشيء كثيرًا، أما إذا كان القيء يسيرًا، فيعفى عنه، هذا هو المشروع، والأحوط لك أن تغسلي ما أصابك، أما الطهارة صحيحة، الطهارة ما تنتقض، الطهارة، لكن ما أصاب الثوب أو الرجل أو غيرها يغسل، هذا هو الأحوط خروجًا من خلاف العلماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14375/حكم-قيء-الطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74212.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16297,"question":"يقول: كيف نقوم بتطهير البسط، وما يسمى بالموكيت عندما تصيبه نجاسة، هل يجب علينا غسله كله بأكمله، أو يكفي أن نغسل مكان النجاسة؟ جزاكم الله خيرًا.","title":"كيفية تطهير البسط (الموكيت)","answer":"الجواب: مثل الأراضي يصب عليه الماء، ويكاثر بالماء ويكفي، النبي ﷺ: \"لما بال الأعرابي في المسجد أمر بأن يصب عليه دلوًا من ماء\" فهكذا في الفرش يصب عليها ماء أكثر من البول، تكاثر، ويكفي، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذًا لا داعي لغسل البساط، أو الموكيت بأكمله؟  الشيخ: صب الماء يكفي على المحل. المقدم: على المحل. الشيخ: يكفي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14994/كيفية-تطهير-البسط-الموكيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753009.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16469,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: نعرفكم بأننا نعمل في الصحراء رعاة للإبل، ونعرفكم بأننا نشك في طهرنا؛ لأنا بعض الأوقات نتوضأ بلا أحذية -أجلكم الله- وندوس على فضلات الإبل، وأحيانًا نصلي عليها، وسمعنا من بعض الناس أن أي شيء تصل إليه الشمس فهو طاهر، فحدثونا عن الحكم الصحيح، وفقكم الله، وجزاكم عنا خيرًا.","title":"حكم بول وروث مأكول اللحم","answer":"الجواب: دوس أبوال الإبل، وأرواث الإبل لا يضر؛ لأن أرواثها طاهرة، وبولها طاهر، وهكذا الغنم والبقر، وبقية مأكول اللحم، فلا يضركم ما يصيب أرجلكم من ذلك، ولا ينبغي لكم الشك بلا دليل، فالأصل الطهارة، فما أصاب الأرجل مما لا تعرفون الأصل فيه الطهارة حتى تعلموا النجاسة، فإذا علمتم النجاسة؛ فاغسلوا الرجل عما أصابها، والحمد لله، وعليكم بالحذر من الوسوسة، وسوء الظن. أما الشمس فلا تطهر الأرض، بل لا بد من صب الماء على البول إذا كان فيها بول؛ يصب عليه الماء، ثبت عنه ﷺ: أن أعرابيًا دخل المسجد -مسجد النبي ﷺ- فبال فيه، فأمر النبي ﷺ أن يصب على بوله سجلًا من ماء، ولما هم الصحابة بزجره قال: لا تزرموه ثم لما فرغ؛ دعاه، وعلمه، قال -عليه الصلاة والسلام- قال: إن هذه المساجد لا يصلح فيها شيء من هذا البول، والقذر لأنها بنيت لذكر الله، والصلاة، وقراءة القرآن، فعلمه ﷺ حتى لا يعود إلى مثل هذا، وأمر الصحابة أن يكفوا عنه؛ لئلا ينجس نفسه إذا قاموا عليه، لئلا ينجس نفسه، أو ينجس بقاعًا كثيرة من المسجد؛ حتى يكمل بوله، ثم علمه ﷺ وأرشده، ثم أمر بدلو من ماء أن يصب على بوله، ولم يقل الشمس تطهره. فالحاصل: أن البول، وغيره من النجاسات لا تكفي الشمس في التطهير، بل إن كان بولًا؛ يصب عليه الماء، وإن كان عذرة غائطًا، أو بعرًا نجسًا، كبعر الحمير، أو البغال؛ ينقل، يؤخذ وينقل إلى بعيد عن المسجد. وإن كان له رطوبة؛ يصب عليه ماء على محل الرطوبة، وإن كان يابسًا ينقل، ولا يضر المسجد، أما إن كان رطبًا، يعني: عذرة رطبة، أو روثًا من روث الحمير، أو البغال، رطبًا؛ ينقل، ويبعد عن المسجد، ويصب على محله الرطب شيء من الماء، يكاثر به، يكون طهرة له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15203/حكم-بول-وروث-ماكول-اللحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81308.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16516,"question":"يقول: إذا تبين لي أثناء أداء الصلاة نجاسة في الثوب؛ فهل أكمل الصلاة، أم أقطعها؟ وهل دم الإنسان، ودم الحيوان نجس؟","title":"حكم المصلي إذا تبين له نجاسة في ثيابه وحكم الدم","answer":"الجواب: إذا علمت نجاسة، وأنت في الصلاة في ثوبك، فهذا فيه تفصيل: إن كان في الإمكان طرح الثوب الذي فيه النجاسة: كالعمامة، والغترة، ثوبين عليك ثوبين، والنجاسة في الأعلى تخلع ذلك، ولا حرج، ويكفي، أو في البشت تخلعه. أما إذا كان لا يمكن ذلك؛ لأن النجاسة في الثوب الأسفل، أو في السراويل، ولا يمكن خلعه؛ فإنك تقطعها، وتغسل النجاسة، وتعيد الصلاة، أو تبدله بثوب طاهر، وتصلي، تعيد الصلاة. أما إذا كان في الإمكان خلع الثوب الذي فيه نجاسة فلا بأس؛ لأن الرسول ﷺ «كان يصلي ذات يوم في نعليه، فأخبره جبرائيل أن فيهما قذرًا؛ فخلعهما، واستمر في صلاته» -عليه الصلاة والسلام- خلعهما، واستمر، ولم يعد أولها. فدل ذلك على أنه إذا أمكن الخلع: كالغترة، أو البشت، أو الثوب الأعلى من الثوبين، إذا كان الثوب الذي تحته ساترًا؛ فإنه يكفي، يخلع ذلك ويكفي، وإلا فعليه أن يقطع الصلاة، ويبدل الثوب، ثوبًا طاهرًا، أو يغسل النجاسة. نعم. والدم كله نجس، دم الحيوانات، وبني آدم كله نجس، إذا كان مسفوحًا، أما إذا كان شيئًا يسيرًا، نقط يسيرة أصابت الإنسان من ذبيحة، أو من إنسان؛ يعفى عنها على الصحيح عند أهل العلم، أو كان الدم ليس من المسفوح، بل هو مما قد يقع في اللحوم، داخل اللحوم بأن حمل لحمًا، فأصابه من اللحم شيء من أثر الدم الذي يكون في اللحم؛ هذا لا يضر، هذا محكوم بطهارته، الدم الذي يكون في اللحوم غير الدم الذي يسفح من العنق عند الذبح. فالمقصود: أن الدم الذي يكون في اللحوم هذا يعفى عنه، وهكذا النقط اليسيرة الشيء اليسير يعفى عنه من الدم الذي يصيب الإنسان من جرح فيه، أو جرح في حيوان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15229/حكم-المصلي-اذا-تبين-له-نجاسة-في-ثيابه-وحكم-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75612.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16766,"question":"يسأل ويقول: إذا كانت ملابس الشخص مبللة بالماء، أو بدنه، ولامس ما هو نجس، أو يشك في نجاسته، هل يؤثر هذا على طهارة البدن، أو الملابس خاصة؟","title":"ما يفعل الشخص عند ملامسة النجاسة؟","answer":"الجواب: إذا لمس بيده وهي رطبة ما يشك في نجاسته؛ ما عليه شيء، الأصل الطهارة، أما إن لمس شيئًا رطبًا نجسًا، أو يده رطبة فيها ماء، ولمس النجس؛ يغسل يده فقط، والباقي ما يضره، ولا يلمس بقية جسده بالنجاسة، فإن لمس شيئًا من جسده بالنجاسة؛ غسل ما أصابه، ما لمسه فقط من بدنه، لا ينبغي له الوسوسة، ينبغي له أن يتقيد بما حصلت به النجاسة فقط، في يده يغسلها، لمس طرف ثوبه، يغسل طرف ثوبه، لمس رجله برطوبة النجاسة؛ يغسل طرف رجله، وهكذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15543/ما-يفعل-الشخص-عند-ملامسة-النجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82214.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16776,"question":"يسأل ويقول: إذا كانت ملابس الشخص مبللة بالماء، أو بدنه، ولامس ما هو نجس، أو يشك في نجاسته، هل يؤثر هذا على طهارة البدن، أو الملابس خاصة؟","title":"ما يفعل الشخص عند ملامسة النجاسة؟","answer":"الجواب: إذا لمس بيده وهي رطبة ما يشك في نجاسته؛ ما عليه شيء، الأصل الطهارة، أما إن لمس شيئًا رطبًا نجسًا، أو يده رطبة فيها ماء، ولمس النجس؛ يغسل يده فقط، والباقي ما يضره، ولا يلمس بقية جسده بالنجاسة، فإن لمس شيئًا من جسده بالنجاسة؛ غسل ما أصابه، ما لمسه فقط من بدنه، لا ينبغي له الوسوسة، ينبغي له أن يتقيد بما حصلت به النجاسة فقط، في يده يغسلها، لمس طرف ثوبه، يغسل طرف ثوبه، لمس رجله برطوبة النجاسة؛ يغسل طرف رجله، وهكذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15543/ما-يفعل-الشخص-عند-ملامسة-النجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82214.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16800,"question":"من منطقة القصيم الأخت المستمعة (ح. ع. م) تقول: عندما أذهب إلى أحد أقاربي، ويحين وقت الصلاة، ويقدمون ثيابًا خاصة للصلاة، وأصلي بها، وأنا كارهة؛ لأنني أرى الصغير، والكبير يصلي فيها، وتوضع في الأرض، ويكون في هذه الغرفة أطفال، فهل صلاتي صحيحة؟ أم يجب علي إعادتها عندما أعود إلى منزلي؟ مع العلم أنني أجلس أحيانًا أكثر من وقت هناك، أفتونا جزاكم الله خيرًا، وعن جميع المسلمين.","title":"حكم من صلت وشكت في طهارة الثياب","answer":"الجواب: الأصل أيها الأخت في الله، الأصل الطهارة، فإذا قدم أهل البيت لك ثيابًا للصلاة فيها، فالأصل الطهارة، والحمد لله، ودعي عنك الوساوس، والظنون السيئة، وإذا كانت ملابسك كافية؛ صلي في ملابسك، إذا كانت ملابسك التي عندك كافية؛ صلي فيها، وإذا كانت غير كافية، وقدموا لك جلالًا تلبسينه، أو سجادة تصلين عليها؛ فلا حرج في ذلك، والأصل الطهارة، والحمد لله، ودعي عنك الوساوس، والظن السيئ، فإذا كنت رأيت ريبة؛ فاسألي، قولي: هذا سليم، هذا طاهر؟ ما في بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15565/حكم-من-صلت-وشكت-في-طهارة-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82305.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]},{"id":16808,"question":"من منطقة القصيم الأخت المستمعة (ح. ع. م) تقول: عندما أذهب إلى أحد أقاربي، ويحين وقت الصلاة، ويقدمون ثيابًا خاصة للصلاة، وأصلي بها، وأنا كارهة؛ لأنني أرى الصغير، والكبير يصلي فيها، وتوضع في الأرض، ويكون في هذه الغرفة أطفال، فهل صلاتي صحيحة؟ أم يجب علي إعادتها عندما أعود إلى منزلي؟ مع العلم أنني أجلس أحيانًا أكثر من وقت هناك، أفتونا جزاكم الله خيرًا، وعن جميع المسلمين.","title":"حكم من صلت وشكت في طهارة الثياب","answer":"الجواب: الأصل أيها الأخت في الله، الأصل الطهارة، فإذا قدم أهل البيت لك ثيابًا للصلاة فيها، فالأصل الطهارة، والحمد لله، ودعي عنك الوساوس، والظنون السيئة، وإذا كانت ملابسك كافية؛ صلي في ملابسك، إذا كانت ملابسك التي عندك كافية؛ صلي فيها، وإذا كانت غير كافية، وقدموا لك جلالًا تلبسينه، أو سجادة تصلين عليها؛ فلا حرج في ذلك، والأصل الطهارة، والحمد لله، ودعي عنك الوساوس، والظن السيئ، فإذا كنت رأيت ريبة؛ فاسألي، قولي: هذا سليم، هذا طاهر؟ ما في بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15565/حكم-من-صلت-وشكت-في-طهارة-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_823/nour_82305.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]},{"id":17199,"question":"السائلة: (ن. ع. م) من الجنوب، تقول سماحة الشيخ: تذكر بأنها معلمة تقوم بإمامة الطالبات في الصلاة، ويصلون في ساحة المدرسة، علمًا بأنها تكون متسخة -أي: غير نظيفة يا شيخ- وذلك من إفطار الطالبات، ويصلون على بعض البسط، ولكنها أيضًا تكون غير نظيفة بالتراب، وقد أخبرت المدرسة بذلك، ولكن لم يتم التغيير؛ نظرًا لعدم وجود إمكانية في ذلك، فما حكم -تقول- صلاتنا؟ وما حكم ذلك لصلاة الطالبات؟ مأجورين.","title":"حكم الصلاة على الفراش المتسخ","answer":"الجواب: لا حرج في ذلك، كونها تأمهن حتى يتعلمن، ويستفدن من صلاتها لا بأس بذلك، ولا بأس بالصلاة على فرش، وإن كانت غير نظيفة، مادام ما فيها نجاسة، وجود التراب عليها، أو بعض الأوراق، أو شيء ما يضر، إذا كانت الأرض طاهرة، والبسط طاهرة، ولو كان فيها بعض الأوساخ لا يضر، يصلى عليها، والطالبات يستفدن من المعلمة إذا صلت بهن، تكون في وسطهن، الإمامة تكون في الوسط؛ في وسط البنات، والنساء. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16021/حكم-الصلاة-على-الفراش-المتسخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59027.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]},{"id":17921,"question":"هذا السائل أخوكم في الله محمد سيد حسن مصري ومقيم بالرياض يسأل عن خروج الدم أثناء الصلاة من الأنف هل يبطل الصلاة؟ وماذا يعمل المصلي في ذلك؟","title":"حكم خروج الدم أثناء الصلاة","answer":"الجواب: إذا خرج الدم من الأنف فلا يخلو إما يكن قليلا فيعفى عنه ويكمل صلاته، يعفى عن الدم اليسير من أنفه أو من أصل أسنانه أو من عينه الشيء اليسير، أو من يده أو رجله يعفى عنه، أما إن كان فاحشًا عرفًا يستفحش في نفسه فإنه يقطع الصلاة ويذهب ويغسل أنفه ويعيد الوضوء. نعم.","link":"https://binbaz.org.sa/fatwas/16944/حكم-خروج-الدم-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78011.mp3","categories":["نواقض الوضوء","النجاسات وإزالتها"]},{"id":18106,"question":"كيف تنصحون من وقع على بعض ملابسه نجاسة، والبعض الآخر لم يقع عليه شيء، هل يغسلهما جميعًا؟ أم يغسل كل جزء على حدة؟","title":"كيفية إزالة النجاسة إذا وقعت على الثوب","answer":"الجواب: يغسل موضع النجاسة فقط، إذا أصاب ثوبه نجاسة غسل موضعها مثل قطرة بول على طرف ثوبه يغسل ما أصابه، أو قطرة دم أصاب المرأة من حيضها أو غيره تغسل محل القطرة، وباقي الثوب طاهر. المقصود أنه يغسل ما أصاب الثوب من بول أو غيره من النجاسة، وباقي الثوب طاهر ليس فيه شيء. المقدم: جزاكم الله خيرًا، ولو غسل النجس مع غير النجس هل في ذلك محذور؟ الشيخ: ما فيه حرج، لكن لا يكن للوسواس، إذا كان من طريق الوسوسة لا، أما إذا كان من باب النظافة لأنه وسخ وأراد أن يغسله كله فلا بأس. أما التكلف والوساوس كما يفعل بعض الناس فيغسل الثوب كله من أجل الوسوسة لا ما ينبغي هذا يغسل ما أصاب الثوب فقط. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17141/كيفية-ازالة-النجاسة-اذا-وقعت-على-الثوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_904/nour_90406.mp3","categories":["النجاسات وإزالتها"," الوسواس بأنواعه"]},{"id":18179,"question":"أبي رجل كبير في السن وهو لا يستطيع السيطرة على نفسه وبطبيعة الحال هو يحتاج إلى التنظيف ويكون منا ذلك وأحيانًا نضطر للكشف عنه فكيف توجهوننا؟ جزاكم الله خيرًا.","title":"حكم النظر إلى عورة كبير السن من أجل تنظيفه","answer":"الجواب: إذا تيسر أن تخدمه زوجته هذا هو الواجب؛ لأن الزوجة لها النظر إلى عورته، فإذا تيسر أن تخدمه زوجته هذا هو الواجب أن تقوم بحاجته إذا كان مضطرًا لذلك لا يستطيع أن يخدم نفسه، فإن لم يتيسر ذلك فينبغي أن يخدمه رجل في هذا الأمر خادم يتولى هذه الأمور التي يحتاجها ولا يباشر العورة، بل يزيل الأذى بواسطة منديل أو خرق يزيل بها الأذى ولا يمس العورة، فإن لم يتيسر ذلك خدمه إحدى بناته أو إحدى أخواته إذا تيسر ذلك مع الاجتهاد والحذر مما لا يجوز، كمس العورة، بل تمس ذلك بخرقة ونحوها لإزالة الأذى إذا كان لا يستطيع أن يزيل الأذى لمرضه أو عجزه أو كبر سنه، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. ومن تولى ذلك فهو مأجور في خدمته سواءً كانت الخادمة بنتًا أو أختًا أو زوجة، فهي على خير عظيم، ولكن لا يتولاه غير الزوجة إذا وجدت الزوجة، للاستغناء بها. فإذا لم توجد الزوجة وتيسر خادم يتولى ذلك ولو بالأجرة إذا كان يستطيع ذلك فهو أولى من تولي النساء لهذا الأمر، فإن لم يتيسر تولاه من أراد احتساب الأجر من بنت أو أخت.. أو غير ذلك. مع الحذر من الخلوة إن كانت الخادمة ليست محرمًا له أجنبية ويكون ما فيه خلوة بل يكون عندها شخص ثالث من أخت أو بنت أو أم.. أو نحو ذلك، حتى لا تكون الخلوة، لقول النبي ﷺ: لا يخلون رجل بامرأة إلا مع ذي محرم عليه الصلاة والسلام. نعم. المقدم: تقول: إن أمها نصحتها بعد الانتهاء من ذلك أن تطلب من والدها السماح؟ الشيخ: أيش أيش؟ المقدم: الأم نصحت ابنتها بعد تنظيف أبيها وتقول: اطلبي من أبيك السماح؟ الشيخ: الواجب مثلما تقدم الزوجة هي تولى هذا الأمر إذا استطاعت، فإن كانت المرأة لا تستطيع لكونها عاجزة أيضًا أو ليس له عنده زوجة بالكلية؛ فإنه يتولى ذلك خادم؛ لأن الرجل مع الرجل أسلم من وجود المرأة مع الرجل، وإن كانت محرمًا له، فإذا تيسر خادم يتولى خدمته وتنظيفه مما يخرج منه فهذا أولى إن تيسر ذلك، فإن لم يتيسر خدمته امرأة من محارمه سواءً كانت بنتًا أو أختًا أو غير ذلك مع الحرص على غض البصر عن بعض الأشياء ومع الحرص على أن يكون بينها وبين العورة خرقة أو منديل تزيل به الأذى. نعم.","link":"https://binbaz.org.sa/fatwas/17218/حكم-النظر-الى-عورة-كبير-السن-من-اجل-تنظيفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85404.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":18182,"question":"ما حكم الصلاة للذي في ثوبه دم بسيط؟ هل تبطل الصلاة إذا كان يعلم بذلك؟","title":"حكم صلاة من في ثوبه دمٌ يسير","answer":"الجواب: الدم اليسير يعفى عنه، الدم اليسير يعفى عنه، أما إن كان كثيرًا عرفًا، فإنه لا يعفى عنه، فإذا صلى وهو يعلم أن في ثوبه أو بدنه دمًا كثيرًا، فصلاته غير صحيحة. أما الدم اليسير يعفى عنه، وهكذا لو كان كثيرًا، لكنه نسيه، أو جهله، وصلى، ولم يعلم إلا بعد الصلاة، فصلاته صحيحة، وهكذا لو كان نجاسة أخرى، كبول، أو غيره في ثوب، أو في بعض البدن، نسيه حتى صلى؛ صلاته صحيحة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17217/حكم-صلاة-من-في-ثوبه-دم-يسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73111.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":18270,"question":"هل تجوز الصلاة في ثوب استفرغ عليه طفل رضيع؟","title":"حكم الصلاة في ثوب قاء عليه طفل رضيع","answer":"الجواب: ينبغي أن يغسل بالنضح، إذا كان الطفل الرضيع لا يأكل الطعام فهو مثل بوله، ينضح بالماء ويصلي فيه، لا يصلي فيه قبل النضح بالماء. نعم.","link":"https://binbaz.org.sa/fatwas/17319/حكم-الصلاة-في-ثوب-قاء-عليه-طفل-رضيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91006.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":18835,"question":"يسأل سماحتكم عن وسخ البهائم أجلكم الله وأجل السامعين على الملابس وعن الدمن -كما يعبر- وهل يؤثر ذلك على طهارة الملابس أو لا؟","title":"حكم بول وروث ما يؤكل لحمه","answer":"الجواب: إذا كان البعر من الحيوانات المأكولة: كالإبل والبقر والغنم لا يضر، لا حرج، ولو أصاب الثياب والبدن؛ لأنه طاهر. أما إذا كان من أرواث الحيوانات التي لا تؤكل: كالحمار والبغل والكلب والقط هذه نجسة، لا بد يزيلها من الثياب، ويطهر الثياب منها، والبدن كذلك، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17970/حكم-بول-وروث-ما-يوكل-لحمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73608.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":19068,"question":"المستمع: هاشم عيسى حسين هاشم بعث برسالة يسأل فيها عن حديث رسول الله ﷺ، ويورد معنى الحديث فيقول: \"إذا ولغ الكلب في إناء فليغسل هذا الإناء سبع مرات بالماء والثامنة بالتراب، أو إحداهن بالتراب\" أو كما قال، وجاء في الحديث الشريف، ويسأل ويقول: هل إذا اكتفينا عن التراب بالصابون لما فيه من مركبات كيماوية نجد بعضها في التراب، والحياة واضحة في هذا الموضوع، فهل يعني هذا أنا قمنا بتوجيه النبي ﷺ نرجو التوجيه والإيضاح؟ جزاكم الله خيرًا.","title":"حكم تطهير الإناء بالمنظفات من ولوغ الكلب","answer":"الجواب: الحديث صحيح عن النبي ﷺ يقول عليه الصلاة والسلام: إذا ولغ الكلب في إناء أحدكم فليغسله سبعًا أولاهن بالتراب رواه مسلم، وفي رواية أخرى اغسلوه سبعًا، وعفروه الثامنة بالتراب فسماها ثامنة لأنها زيادة عن الغسلات السبع، وإلا فالغسلات سبع، والثامنة تراب مع إحدى الغسلات، والأفضل أن تكون مع الأولى حتى تكون الغسلات الأخيرة منقية للإناء من جميع الوجوه. وإذا تيسر التراب فهو أولى من غيره عملًا بالحديث الصحيح، ولعل هناك سرًا خاصًا في التراب، فمهما وجد التراب فهو أولى في الامتثال لأمر النبي ﷺ. أما إذا لم يتيسر التراب فالصابون والإشنان وغيرهما مما يزيل الآثار يكفي إن شاء الله، والحمد لله، لكن إذا تيسر التراب فهو أولى في الامتثال وأحب إلي؛ لأنه نص عليه النبي عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18275/حكم-تطهير-الاناء-بالمنظفات-من-ولوغ-الكلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79705.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":19397,"question":"أختنا تسأل وتقول: إذا بال طفل في مكان ما، أي ليس في الحمام - أعزكم الله والسامعين - فمر شخص وهو لا يعلم أن هذا المكان به بول، وكان ذلك الشخص متوضئا فداس على ذلك البول أو مشى عليه، فهل ينتقض وضوؤه","title":"حكم وضوء من وطئ نجاسة","answer":"الجواب: إذا داس الإنسان على البول، أو على غيره من النجاسات لا ينتقض وضوؤه، ولكن إذا كان البول رطبا أو رجله رطبة، غسلها إذا علم، أما إذا لم يعلم فلا شيء عليه، لكن إذا علم وكان البول أو غيره رطبا غسل رجله، أو كانت رجله رطبة وداس على البول ونحوها غسلها، غسل ما أصابها، أما إن كان محل البول يابسا، أو غيره من النجاسة يابسا ورجله يابسة، فلا شيء عليه، لأنه لا يتأثر بذلك، وهكذا لو لم يعلم أن هذا نجس وصلى فإنه لا يضره ذلك، كما لو صلى في ثوب نجس لم يعلم بذلك، حتى فرغ من الصلاة فإنه لا يعيد على الصحيح. وهكذا لو صلى في بقعة نجسة، ويظنها طاهرة ولكن لم يعلم إلا بعد الصلاة، فصلاته صحيحة على الصحيح.\nوهكذا لو صلى وقد أصاب رجله أو يده نجاسة ما علم بها إلا بعد الصلاة، صلاته صحيحة على الصحيح. والحجة في ذلك أنه صلى الله عليه وسلم صلى ذات يوم في نعليه وكان فيهما قذر، فأخبره جبرائيل عليه الصلاة والسلام، أن فيهما قذرا فخلعهما ولم يعد أول الصلاة، فدل ذلك على أن الذي لم يعلم معذور، فهكذا إذا أكمل. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/18620/حكم-وضوء-من-وطى-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93504.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":19633,"question":"المستمعة أم محمد تقول: امرأة بعد تغسيل أطفالها من النجاسة يأتيها رذاذ ماء، فهل يعتبر نجس أم لا؟","title":"حكم رذاذ الماء المتطاير عند تغسيل الأطفال من النجاسة","answer":"الجواب: إذا كان فيه النجاسة قبل أن تطهر من النجاسة يكون نجس، أما إذا كان قد زالت النجاسة من أبنائها فيكون طاهر، فعليها التحرز عند غسل الطفل، أو ثيابه؛ تتحرز حتى لا يأتيها شيء من النجاسة. نعم.","link":"https://binbaz.org.sa/fatwas/18900/حكم-رذاذ-الماء-المتطاير-عند-تغسيل-الاطفال-من-النجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94831.mp3","categories":["النجاسات وإزالتها","الطهارة لصحة الصلاة","قضايا المرأة"]}]
